const CACHE_NAME = 'lore-cache-v2';
const urlsToCache = [
  '/',
  '/index.html',
  '/manifest.json',
  'https://cdn.tailwindcss.com',
  'https://cdn.tailwindcss.com?plugins=typography',
  'https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js',
  'https://cdn-icons-png.flaticon.com/512/3976/3976625.png'
];

self.addEventListener('install', (event) => {
  self.skipWaiting();
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then((cache) => {
        return cache.addAll(urlsToCache);
      })
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((cacheNames) => {
      return Promise.all(
        cacheNames.map((cacheName) => {
          if (cacheName !== CACHE_NAME) {
            return caches.delete(cacheName);
          }
        })
      );
    })
  );
  return self.clients.claim();
});

// Stale-While-Revalidate Strategy
self.addEventListener('fetch', (event) => {
  // Skip cross-origin requests that might be opaque/problematic unless explicitly cached
  if (!event.request.url.startsWith('http')) return;

  event.respondWith(
    caches.match(event.request).then((cachedResponse) => {
      const fetchPromise = fetch(event.request).then((networkResponse) => {
        // Cache valid responses
        if (networkResponse && networkResponse.status === 200) {
          const responseClone = networkResponse.clone();
          caches.open(CACHE_NAME).then((cache) => {
            cache.put(event.request, responseClone);
          });
        }
        return networkResponse;
      }).catch(() => {
        // Network failure
        return cachedResponse;
      });

      // Return cached response immediately if available, otherwise wait for network
      return cachedResponse || fetchPromise;
    })
  );
});

import React from 'react';
import { BookProject } from '../types';
import { Plus, Clock, Trash2, Download, BookCopy, Layers, Feather, Loader2 } from 'lucide-react';

interface DashboardProps {
  projects: BookProject[];
  onCreateProject: () => void;
  onSelectProject: (project: BookProject) => void;
  onDeleteProject: (id: string, e: React.MouseEvent) => void;
  onCreateSequel?: (project: BookProject) => void;
  generatingProjectId?: string | null;
}

export const Dashboard: React.FC<DashboardProps> = ({ 
  projects, 
  onCreateProject, 
  onSelectProject,
  onDeleteProject,
  onCreateSequel,
  generatingProjectId
}) => {

  const formatDate = (timestamp: number) => {
    return new Date(timestamp).toLocaleDateString('en-US', {
      month: 'long',
      day: 'numeric',
      year: 'numeric'
    });
  };

  const handleBackup = (e: React.MouseEvent, project: BookProject) => {
    e.stopPropagation();
    const element = document.createElement("a");
    const file = new Blob([JSON.stringify(project, null, 2)], {type: 'application/json'});
    element.href = URL.createObjectURL(file);
    element.download = `backup_${project.title.replace(/[^a-z0-9]/gi, '_').toLowerCase()}.json`;
    document.body.appendChild(element);
    element.click();
    document.body.removeChild(element);
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900">
      {/* Header */}
      <div className="bg-blue-950 border-b border-blue-900 text-white shadow-md">
        <div className="max-w-6xl mx-auto px-6 md:px-12 h-20 flex items-center justify-between">
          <div className="flex items-center gap-3">
             <div className="bg-white/10 text-blue-100 p-2 rounded-lg backdrop-blur-sm border border-white/10">
               <Feather size={20} strokeWidth={2} />
             </div>
             <div>
                <h1 className="font-serif text-2xl font-bold tracking-tight">Lore</h1>
                <p className="text-[11px] text-blue-200 font-medium opacity-80 tracking-wide">An R² Technologies Project.</p>
             </div>
          </div>
          <button 
            onClick={onCreateProject}
            className="bg-blue-600 hover:bg-blue-500 text-white px-5 py-2.5 rounded-lg font-medium text-sm flex items-center gap-2 transition-all shadow-lg shadow-blue-900/20 hover:shadow-blue-600/20 hover:-translate-y-0.5"
          >
            <Plus size={18} />
            New Manuscript
          </button>
        </div>
      </div>

      {/* Projects List */}
      <div className="max-w-6xl mx-auto px-6 md:px-12 py-12">
        <div className="flex items-end justify-between mb-8">
          <h2 className="text-2xl font-serif font-bold text-slate-900">My Library</h2>
          <div className="text-sm text-slate-500 font-medium">
            {projects.length} {projects.length === 1 ? 'Project' : 'Projects'}
          </div>
        </div>

        {projects.length === 0 ? (
          <div className="text-center py-24 bg-white rounded-xl border-2 border-dashed border-slate-200 shadow-sm">
            <div className="w-20 h-20 bg-blue-50 rounded-full flex items-center justify-center mx-auto mb-6 text-blue-500">
              <Feather size={32} strokeWidth={1.5} />
            </div>
            <h3 className="text-lg font-bold text-slate-900 mb-2">No manuscripts yet</h3>
            <p className="text-slate-500 max-w-md mx-auto mb-8 font-light leading-relaxed">
              Begin your journey by creating a new project. Transform your spoken stories into a written masterpiece.
            </p>
            <button 
              onClick={onCreateProject}
              className="text-blue-600 font-semibold border-b-2 border-blue-100 hover:border-blue-600 pb-0.5 transition-all"
            >
              Start Writing &rarr;
            </button>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {projects.map(project => {
              const isGenerating = generatingProjectId === project.id;

              return (
              <div 
                key={project.id}
                onClick={() => onSelectProject(project)}
                className={`group bg-white rounded-xl border border-slate-200 shadow-sm hover:shadow-xl hover:shadow-blue-900/5 hover:border-blue-200 transition-all cursor-pointer flex flex-col h-72 relative overflow-hidden ${isGenerating ? 'ring-2 ring-blue-500 ring-offset-2' : ''}`}
              >
                <div className="absolute top-0 left-0 w-full h-1.5 bg-gradient-to-r from-blue-600 to-blue-400 opacity-0 group-hover:opacity-100 transition-opacity"></div>

                <div className="p-8 flex-1 flex flex-col relative z-10">
                   {/* Decorative background letter */}
                   <span className="font-serif text-8xl text-slate-50 font-bold absolute -bottom-4 -right-4 select-none group-hover:text-blue-50 transition-colors duration-300 -z-10">
                      {project.title.charAt(0).toUpperCase()}
                   </span>

                  <div className="relative">
                    <div className="flex items-center justify-between mb-3">
                      <div className="flex items-center gap-2 text-xs text-blue-600 font-bold uppercase tracking-wider">
                        <div className={`w-2 h-2 rounded-full ${isGenerating ? 'bg-blue-500 animate-pulse' : 'bg-blue-500'}`}></div>
                        {isGenerating ? 'Writing Now...' : project.outline ? 'In Progress' : 'Drafting'}
                      </div>
                      {project.seriesId && (
                         <div className="flex items-center gap-1 text-[10px] text-purple-600 font-bold uppercase tracking-wider bg-purple-50 px-2 py-0.5 rounded-full border border-purple-100">
                            <Layers size={10} />
                            {project.seriesIndex ? `Vol. ${project.seriesIndex}` : 'Series'}
                         </div>
                      )}
                    </div>
                    <h3 className="font-serif font-bold text-xl text-slate-900 mb-3 line-clamp-2 leading-tight group-hover:text-blue-700 transition-colors">
                      {project.title}
                    </h3>
                    <div className="flex items-center gap-2 text-xs text-slate-400 font-medium">
                      {isGenerating ? (
                        <div className="text-blue-600 flex items-center gap-1">
                           <Loader2 size={12} className="animate-spin" /> Auto-Saving...
                        </div>
                      ) : (
                        <>
                          <Clock size={12} />
                          Edited {formatDate(project.lastModified)}
                        </>
                      )}
                    </div>
                  </div>
                </div>

                <div className="bg-slate-50/50 border-t border-slate-100 px-6 py-4 flex items-center justify-between backdrop-blur-sm relative z-20">
                   <div className="flex gap-2">
                      <span className="text-xs font-semibold px-2.5 py-1 bg-white border border-slate-200 rounded-md text-slate-600 shadow-sm group-hover:border-blue-200 group-hover:text-blue-700 transition-colors">
                        {project.outline ? `${project.outline.chapters.length} Chapters` : 'Source Gathering'}
                      </span>
                   </div>

                   <div className="flex gap-1 transform translate-y-0 transition-all duration-200">
                      {onCreateSequel && project.outline && (
                        <button 
                          onClick={(e) => { e.stopPropagation(); onCreateSequel(project); }}
                          className="p-2 text-slate-400 hover:text-purple-600 hover:bg-purple-50 rounded-md transition-colors relative z-30"
                          title="Create Sequel / Next in Series"
                        >
                          <BookCopy size={16} />
                        </button>
                      )}
                      <button 
                        onClick={(e) => handleBackup(e, project)}
                        className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-md transition-colors relative z-30"
                        title="Backup"
                      >
                        <Download size={16} />
                      </button>
                      <button 
                        onClick={(e) => onDeleteProject(project.id, e)}
                        className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-md transition-colors relative z-30"
                        title="Delete"
                      >
                        <Trash2 size={16} />
                      </button>
                   </div>
                </div>
              </div>
            )})}
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { ChapterContent, BookOutline } from '../types';
import { ChevronLeft, ChevronRight, Loader2, Download, PenLine, Save, Headphones, Play, Square, FileText, Image as ImageIcon, Wand2, Menu, X, Sparkles } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import { generateSpeech, generateImage, refineChapterText } from '../services/gemini';
import { Notification } from './Notification';

interface BookReaderProps {
  outline: BookOutline;
  chapters: ChapterContent[];
  onChapterUpdate?: (chapter: ChapterContent) => void;
  selectedVoice?: string;
  onVoiceChange?: (voice: string) => void;
  onUpdateOutline?: (outline: BookOutline) => void;
}

const DEFAULT_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbxntoxi2DILyS_K3zQlZx9DSUDMupWW9x_p4sfWkCsKzB1Yv38SVSaylfVIX_bAOp4_/exec";

// Audio Cache to prevent re-fetching
const audioCache = new Map<string, AudioBuffer>();

// Helpers for Gemini Audio (PCM)
function decode(base64: string) {
  try {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  } catch (e) {
    console.error("Audio decoding failed", e);
    return new Uint8Array(0);
  }
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number = 24000,
  numChannels: number = 1
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;

  // Create buffer at the SOURCE sample rate (Gemini is 24000Hz)
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

export const BookReader: React.FC<BookReaderProps> = ({ 
  outline, 
  chapters, 
  onChapterUpdate, 
  selectedVoice, 
  onVoiceChange,
  onUpdateOutline
}) => {
  const [currentChapterIndex, setCurrentChapterIndex] = useState(0);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isPlaying, setIsPlaying] = useState(false);
  const [audioLoading, setAudioLoading] = useState(false);
  const [isExporting, setIsExporting] = useState(false);
  const [isExportingDocs, setIsExportingDocs] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editContent, setEditContent] = useState('');
  const [polishInstruction, setPolishInstruction] = useState('');
  const [isPolishing, setIsPolishing] = useState(false);
  const [isCoverGenerating, setIsCoverGenerating] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'error' | 'success'} | null>(null);

  const audioContextRef = useRef<AudioContext | null>(null);
  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  const currentChapter = chapters[currentChapterIndex];

  useEffect(() => {
    stopAudio();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentChapterIndex]);

  const showNotification = (message: string, type: 'error' | 'success' = 'success') => {
    setNotification({ message, type });
    setTimeout(() => setNotification(null), 4000);
  };

  const stopAudio = () => {
    if (audioSourceRef.current) {
      try { audioSourceRef.current.stop(); } catch(e) {}
      audioSourceRef.current = null;
    }
    setIsPlaying(false);
  };

  const playChapterAudio = async () => {
    if (isPlaying) {
      stopAudio();
      return;
    }

    if (!currentChapter?.content) return;

    let silentSource: AudioBufferSourceNode | null = null;

    try {
      if (!audioContextRef.current) {
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
        audioContextRef.current = new AudioContextClass();
      }

      const ctx = audioContextRef.current;

      if (ctx.state === 'suspended') {
        await ctx.resume();
      }

      // Play silent loop to keep mobile audio session alive
      const silentBuffer = ctx.createBuffer(1, 22050, 22050); 
      silentSource = ctx.createBufferSource();
      silentSource.buffer = silentBuffer;
      silentSource.loop = true;
      silentSource.connect(ctx.destination);
      silentSource.start();

    } catch (e) {
      console.error("Audio unlock failed", e);
      showNotification("Could not access audio hardware.", 'error');
      return;
    }

    const cacheKey = `${currentChapter.chapterNumber}-${selectedVoice}-${currentChapter.content.length}`;
    if (audioCache.has(cacheKey)) {
        if (silentSource) (silentSource as AudioBufferSourceNode).stop();
        playBuffer(audioCache.get(cacheKey)!);
        return;
    }

    setAudioLoading(true);

    try {
      const pcmBase64 = await generateSpeech(currentChapter.content.slice(0, 5000), selectedVoice || 'Kore');

      const audioCtx = audioContextRef.current;
      if (!audioCtx) throw new Error("Audio context lost");

      const pcmData = decode(pcmBase64);
      const audioBuffer = await decodeAudioData(pcmData, audioCtx, 24000);

      audioCache.set(cacheKey, audioBuffer);

      if (silentSource) (silentSource as AudioBufferSourceNode).stop();

      playBuffer(audioBuffer);

    } catch (err: any) {
      console.error("Audio playback failed", err);
      if (silentSource) {
        try { (silentSource as AudioBufferSourceNode).stop(); } catch(e) {}
      }
      showNotification("Failed to generate audio. " + (err.message || ""), 'error');
    } finally {
      setAudioLoading(false);
    }
  };

  const playBuffer = (buffer: AudioBuffer) => {
    if (!audioContextRef.current) return;
    const ctx = audioContextRef.current;

    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.connect(ctx.destination);
    source.onended = () => setIsPlaying(false);

    audioSourceRef.current = source;
    source.start();
    setIsPlaying(true);
  };

  const handleDownloadPDF = async () => {
    setIsExporting(true);

    // Create a temporary hidden container to render the clean book structure
    const container = document.createElement('div');
    container.style.position = 'absolute';
    container.style.left = '-9999px';
    container.style.top = '0px';
    container.style.width = '800px'; // Fixed width for A4 consistency
    document.body.appendChild(container);

    try {
       if (!(window as any).html2pdf) {
         throw new Error("PDF Library not loaded. Please refresh.");
       }

       const styles = `
         <style>
           @import url('https://fonts.googleapis.com/css2?family=Merriweather:ital,wght@0,300;0,400;0,700;1,300&display=swap');
           .pdf-body { font-family: 'Merriweather', serif; color: #000; line-height: 1.8; padding: 40px; background: white; }
           .pdf-h1 { font-size: 48px; font-weight: 700; margin-bottom: 20px; text-align: center; color: #1e293b; }
           .pdf-h2 { font-size: 32px; font-weight: 700; margin-top: 40px; margin-bottom: 20px; page-break-after: avoid; color: #1e293b; }
           .pdf-p { margin-bottom: 16px; text-align: justify; font-size: 14px; }
           .pdf-cover { max-width: 100%; height: auto; margin: 40px auto; display: block; border: 1px solid #eee; }
           .pdf-title-page { min-height: 900px; display: flex; flex-direction: column; justify-content: center; align-items: center; text-align: center; page-break-after: always; }
           .pdf-chapter { page-break-before: always; margin-top: 40px; }
           .pdf-footer { text-align: center; font-size: 10px; color: #94a3b8; margin-top: 50px; border-top: 1px solid #e2e8f0; padding-top: 10px; }
         </style>
       `;

       const renderMarkdown = (text: string) => {
          // Simple replacement for basic markdown in PDF
          return text
           .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
           .replace(/\*(.*?)\*/g, '<em>$1</em>')
           .replace(/\n\n/g, '</p><p class="pdf-p">')
           .replace(/^# (.*$)/gim, '<h3 class="pdf-h3">$1</h3>')
           .replace(/^## (.*$)/gim, '<h4 class="pdf-h4">$1</h4>');
       };

       const chaptersHtml = chapters.map(chap => `
           <div class="pdf-chapter">
              <div style="text-align: center; margin-bottom: 40px; margin-top: 20px;">
                 <span style="text-transform: uppercase; letter-spacing: 2px; font-size: 12px; border-bottom: 1px solid #000; padding-bottom: 5px;">Chapter ${chap.chapterNumber}</span>
                 <h2 class="pdf-h2">${chap.title}</h2>
              </div>
              <p class="pdf-p">${renderMarkdown(chap.content)}</p>
           </div>
       `).join('');

       container.innerHTML = `
         <div class="pdf-body">
           ${styles}
           <div class="pdf-title-page">
             <h1 class="pdf-h1">${outline.title}</h1>
             <p style="text-transform: uppercase; letter-spacing: 2px; color: #64748b;">A Lore Original</p>
             ${outline.coverImage ? `<img src="data:image/jpeg;base64,${outline.coverImage}" class="pdf-cover" style="max-width: 350px;" />` : ''}
             <p style="font-style: italic; max-width: 600px; margin-top: 40px; color: #475569;">${outline.description}</p>
           </div>
           ${chaptersHtml}
           <div class="pdf-footer">Generated with Lore</div>
         </div>
       `;

       const opt = {
         margin: 0.5,
         filename: `${outline.title.replace(/[^a-z0-9]/gi, '_').toLowerCase()}.pdf`,
         image: { type: 'jpeg', quality: 0.95 },
         // Lower scale for reliability on mobile devices (prevents canvas memory crashes)
         html2canvas: { scale: 1.5, useCORS: true, letterRendering: true },
         jsPDF: { unit: 'in', format: 'letter', orientation: 'portrait' },
         pagebreak: { mode: ['avoid-all', 'css', 'legacy'] }
       };

       await (window as any).html2pdf().set(opt).from(container).save();

       showNotification("PDF downloaded successfully!");

    } catch (e) {
       console.error("PDF Export failed", e);
       showNotification("Visual PDF failed (file too large). Try Export to Docs.", 'error');
    } finally {
       document.body.removeChild(container);
       setIsExporting(false);
    }
  };

  const handleExportDocs = async () => {
    setIsExportingDocs(true);

    const scriptUrl = prompt("Enter Google Apps Script URL:", DEFAULT_SCRIPT_URL);
    if (!scriptUrl) {
      setIsExportingDocs(false);
      return;
    }

    try {
      await fetch(scriptUrl, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title: outline.title,
          description: outline.description,
          chapters: chapters.map(c => ({
            chapterNumber: c.chapterNumber,
            title: c.title,
            content: c.content
          }))
        })
      });
      showNotification("Export request sent to Google Docs!");
    } catch (e) {
      console.error(e);
      showNotification("Docs export failed.", 'error');
    } finally {
      setIsExportingDocs(false);
    }
  };

  const startEditing = () => {
    if (!currentChapter) return;
    setEditContent(currentChapter.content);
    setIsEditing(true);
  };

  const saveEditing = () => {
    if (!currentChapter || !onChapterUpdate) return;
    onChapterUpdate({
      ...currentChapter,
      content: editContent
    });
    setIsEditing(false);
    showNotification("Changes saved.");
  };

  const cancelEditing = () => {
    setIsEditing(false);
    setPolishInstruction('');
  };

  const handlePolish = async () => {
    if (!polishInstruction.trim()) return;
    setIsPolishing(true);
    try {
      const polished = await refineChapterText(editContent, polishInstruction);
      setEditContent(polished);
      setPolishInstruction('');
      showNotification("Text refined!");
    } catch (e) {
      console.error(e);
      showNotification("Polish failed.", 'error');
    } finally {
      setIsPolishing(false);
    }
  };

  const handleGenerateCover = async () => {
    if (!onUpdateOutline) return;
    setIsCoverGenerating(true);
    try {
      const prompt = `A professional, high-quality book cover for a book titled "${outline.title}". 
      Description: ${outline.description}. 
      Style: Minimalist, modern, striking typography, best-selling aesthetic.`;

      const base64Image = await generateImage(prompt, '1:1');
      onUpdateOutline({
        ...outline,
        coverImage: base64Image
      });
      showNotification("Cover updated!");
    } catch (e) {
      console.error(e);
      showNotification("Failed to generate cover.", 'error');
    } finally {
      setIsCoverGenerating(false);
    }
  };

  const handleChapterSelect = (idx: number) => {
    setCurrentChapterIndex(idx);
    if (window.innerWidth < 768) {
      setIsSidebarOpen(false);
    }
  };

  return (
    <>
      {notification && (
        <Notification message={notification.message} type={notification.type} onClose={() => setNotification(null)} />
      )}

      <div className="flex flex-col md:flex-row h-[calc(100vh-4rem)] bg-slate-50 relative overflow-hidden">

        {/* Sidebar */}
        <div className={`
            flex-col bg-white border-r border-slate-200 flex-shrink-0 transition-all duration-300 z-30
            ${isSidebarOpen ? 'fixed inset-0 w-full flex md:static md:w-80' : 'hidden md:flex md:w-0 md:overflow-hidden'}
        `}>
          <div className="p-6 border-b border-slate-100 flex-shrink-0 flex justify-between items-start">
             <div className="overflow-hidden">
               <h3 className="font-bold text-slate-900 font-serif mb-1 truncate">{outline.title}</h3>
               <p className="text-xs text-slate-500 uppercase tracking-wider font-semibold">Table of Contents</p>
             </div>
             <button onClick={() => setIsSidebarOpen(false)} className="md:hidden p-1 text-slate-400 hover:text-slate-600">
               <X size={24} />
             </button>
          </div>

          {/* Unified Scrollable Area: Holds both chapters and controls */}
          <div className="flex-1 overflow-y-auto">
             <div className="p-4 space-y-2">
               {chapters.map((chap, idx) => (
                 <button
                   key={chap.chapterNumber}
                   onClick={() => handleChapterSelect(idx)}
                   className={`w-full text-left p-3 rounded-lg text-sm transition-all border ${
                     currentChapterIndex === idx 
                     ? 'bg-blue-50 border-blue-200 text-blue-800 font-bold shadow-sm' 
                     : 'border-transparent hover:bg-slate-50 text-slate-600'
                   }`}
                 >
                   <div className="flex justify-between items-center mb-1">
                      <span className="text-xs opacity-70 uppercase tracking-wide">Chapter {chap.chapterNumber}</span>
                      {chap.isGenerating && <Loader2 size={12} className="animate-spin text-blue-500"/>}
                   </div>
                   <div className="truncate">{chap.title}</div>
                 </button>
               ))}
             </div>

             <div className="p-4 border-t border-slate-100 bg-slate-50/50 space-y-3">
                <div className="bg-white p-3 rounded-lg border border-slate-200 shadow-sm">
                   <div className="flex items-center gap-2 mb-2 text-xs font-bold text-slate-400 uppercase tracking-wider">
                     <Headphones size={12} /> Audiobook
                   </div>
                   <select 
                      value={selectedVoice}
                      onChange={(e) => onVoiceChange && onVoiceChange(e.target.value)}
                      className="w-full text-sm p-2 bg-slate-50 border border-slate-200 rounded mb-2 outline-none focus:border-blue-300"
                   >
                     <option value="Kore">Kore (Balanced)</option>
                     <option value="Puck">Puck (Energetic)</option>
                     <option value="Fenrir">Fenrir (Deep)</option>
                     <option value="Charon">Charon (Calm)</option>
                   </select>
                   <button 
                     onClick={playChapterAudio}
                     disabled={audioLoading || !currentChapter || currentChapter.isGenerating}
                     className={`w-full py-2 rounded-md font-bold text-sm text-white flex items-center justify-center gap-2 transition-all ${isPlaying ? 'bg-slate-800 hover:bg-slate-900' : 'bg-blue-600 hover:bg-blue-500 shadow-sm'}`}
                   >
                     {audioLoading ? <Loader2 size={14} className="animate-spin" /> : isPlaying ? <Square size={14} fill="currentColor" /> : <Play size={14} fill="currentColor" />}
                     {isPlaying ? 'Stop Reading' : 'Read Chapter'}
                   </button>
                </div>

                <div className="bg-white p-4 rounded-lg border border-slate-200 shadow-sm">
                   <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3">Design & Export</div>

                   <div className="mb-4">
                     {outline.coverImage ? (
                       <div className="relative group rounded-md overflow-hidden mb-2 border border-slate-100 shadow-sm">
                          <img src={`data:image/jpeg;base64,${outline.coverImage}`} alt="Cover" className="w-full h-full object-cover aspect-square" />
                          <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                             <button onClick={handleGenerateCover} className="text-white text-xs font-bold flex items-center gap-1 hover:underline">
                                <ImageIcon size={12} /> Regenerate
                             </button>
                          </div>
                       </div>
                     ) : (
                       <button 
                         onClick={handleGenerateCover}
                         disabled={isCoverGenerating}
                         className="w-full py-2 px-3 bg-purple-50 hover:bg-purple-100 text-purple-700 rounded-md text-xs font-bold flex items-center justify-center gap-2 transition-all mb-2"
                       >
                         {isCoverGenerating ? <Loader2 size={12} className="animate-spin" /> : <Sparkles size={12} />}
                         Generate Full Cover
                       </button>
                     )}
                   </div>

                   <button 
                     onClick={handleDownloadPDF}
                     disabled={isExporting}
                     className="w-full flex items-center gap-2 text-slate-600 hover:text-blue-700 hover:bg-slate-50 p-2 rounded-md text-sm font-medium transition-colors mb-1"
                   >
                     {isExporting ? <Loader2 size={16} className="animate-spin" /> : <Download size={16} />}
                     Download E-Book (PDF)
                   </button>
                   <button 
                     onClick={handleExportDocs}
                     disabled={isExportingDocs}
                     className="w-full flex items-center gap-2 text-slate-600 hover:text-blue-700 hover:bg-slate-50 p-2 rounded-md text-sm font-medium transition-colors"
                   >
                     {isExportingDocs ? <Loader2 size={16} className="animate-spin" /> : <FileText size={16} />}
                     Export to Docs
                   </button>
                </div>
             </div>
          </div>

        </div>

        {/* Reader Content */}
        <div className="flex-1 flex flex-col h-full overflow-hidden bg-slate-50 relative w-full">

           <div className="md:hidden h-14 bg-white border-b border-slate-200 flex items-center px-4 shrink-0 justify-between">
              <button onClick={() => setIsSidebarOpen(true)} className="p-2 -ml-2 text-slate-600 hover:bg-slate-100 rounded-lg">
                 <Menu size={24} />
              </button>
              <span className="font-serif font-bold text-slate-900 truncate max-w-[200px]">
                 {currentChapter ? `Ch ${currentChapter.chapterNumber}: ${currentChapter.title}` : 'Reader'}
              </span>
              <div className="w-8"></div>
           </div>

           <div className="hidden md:block absolute top-4 left-4 z-20">
              <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 bg-white shadow-md rounded-lg border border-slate-200 text-slate-600 hover:text-blue-600 transition-colors">
                 {isSidebarOpen ? <ChevronLeft size={20} /> : <ChevronRight size={20} />}
              </button>
           </div>

           <div className="flex-1 overflow-y-auto p-4 md:p-12 scroll-smooth">
             <div className="max-w-3xl mx-auto bg-white shadow-xl shadow-slate-200/50 min-h-[80vh] p-6 md:p-16 rounded-xl relative border border-slate-100">

                <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-blue-100 via-blue-50 to-blue-100 opacity-50"></div>

                {!currentChapter ? (
                  <div className="flex flex-col items-center justify-center h-64 text-slate-400">
                    <Loader2 size={40} className="animate-spin mb-4 text-blue-200" />
                    <p>Loading Manuscript...</p>
                  </div>
                ) : (
                  <>
                    <div className="mb-8 pb-8 border-b border-slate-100">
                       <span className="text-xs font-bold tracking-[0.2em] text-slate-400 uppercase mb-2 block text-center">Chapter {currentChapter.chapterNumber}</span>
                       <h2 className="text-2xl md:text-4xl font-serif font-bold text-slate-900 text-center leading-tight">{currentChapter.title}</h2>
                    </div>

                    {isEditing ? (
                       <div className="animate-in fade-in">
                          <textarea 
                             value={editContent}
                             onChange={(e) => setEditContent(e.target.value)}
                             className="w-full h-[60vh] p-4 font-serif text-lg leading-relaxed text-slate-800 border-2 border-blue-100 rounded-lg outline-none focus:ring-2 focus:ring-blue-200 resize-y mb-4"
                          />

                          <div className="bg-blue-50 p-4 rounded-xl border border-blue-100 mb-6 flex gap-3 items-center">
                             <div className="bg-blue-200 p-2 rounded-full text-blue-700"><Wand2 size={16} /></div>
                             <div className="flex-1">
                                <input 
                                  value={polishInstruction}
                                  onChange={(e) => setPolishInstruction(e.target.value)}
                                  placeholder="Ask AI to polish (e.g., 'Make it more dramatic')"
                                  className="w-full bg-white border border-blue-200 rounded px-3 py-2 text-sm outline-none focus:border-blue-400"
                                  onKeyDown={(e) => e.key === 'Enter' && handlePolish()}
                                />
                             </div>
                             <button 
                               onClick={handlePolish}
                               disabled={isPolishing || !polishInstruction.trim()}
                               className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white text-sm font-bold rounded-lg transition-colors disabled:opacity-50"
                             >
                               {isPolishing ? <Loader2 size={16} className="animate-spin" /> : 'Refine'}
                             </button>
                          </div>

                          <div className="flex justify-end gap-3 sticky bottom-0 bg-white pt-4 border-t border-slate-100">
                             <button onClick={cancelEditing} className="px-5 py-2.5 text-slate-600 font-bold text-sm hover:bg-slate-100 rounded-lg">Cancel</button>
                             <button onClick={saveEditing} className="px-5 py-2.5 bg-emerald-600 hover:bg-emerald-500 text-white font-bold text-sm rounded-lg shadow-lg shadow-emerald-200 flex items-center gap-2">
                                <Save size={16} /> Save Changes
                             </button>
                          </div>
                       </div>
                    ) : (
                      <div className="prose prose-lg prose-slate font-serif max-w-none prose-headings:font-sans prose-headings:font-bold prose-p:leading-loose text-slate-800">
                         {currentChapter.isGenerating ? (
                           <div className="space-y-4 animate-pulse">
                              <div className="h-4 bg-slate-100 rounded w-full"></div>
                              <div className="h-4 bg-slate-100 rounded w-11/12"></div>
                              <div className="h-4 bg-slate-100 rounded w-full"></div>
                              <div className="py-8 text-center text-slate-400 text-sm font-sans flex items-center justify-center gap-2">
                                <Loader2 size={16} className="animate-spin" /> Writing in progress...
                              </div>
                           </div>
                         ) : (
                           <div className="relative group min-h-[200px]">
                              <ReactMarkdown>{currentChapter.content}</ReactMarkdown>
                              <button 
                                onClick={startEditing}
                                className="absolute top-0 right-0 p-2 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-lg opacity-0 group-hover:opacity-100 transition-all"
                                title="Edit Text"
                              >
                                <PenLine size={20} />
                              </button>
                           </div>
                         )}
                      </div>
                    )}
                  </>
                )}
             </div>

             <div className="max-w-3xl mx-auto mt-8 flex justify-between items-center text-sm font-medium text-slate-500 pb-24 md:pb-12 px-4">
                <button 
                  onClick={() => setCurrentChapterIndex(prev => Math.max(0, prev - 1))}
                  disabled={currentChapterIndex === 0}
                  className="flex items-center gap-2 hover:text-blue-600 disabled:opacity-30 disabled:hover:text-slate-500 transition-colors px-4 py-2 hover:bg-white rounded-full"
                >
                  <ChevronLeft size={16} /> Previous
                </button>
                <span>{currentChapterIndex + 1} / {chapters.length}</span>
                <button 
                  onClick={() => setCurrentChapterIndex(prev => Math.min(chapters.length - 1, prev + 1))}
                  disabled={currentChapterIndex === chapters.length - 1}
                  className="flex items-center gap-2 hover:text-blue-600 disabled:opacity-30 disabled:hover:text-slate-500 transition-colors px-4 py-2 hover:bg-white rounded-full"
                >
                  Next <ChevronRight size={16} />
                </button>
             </div>
           </div>
        </div>
      </div>
    </>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { ChapterContent, BookOutline } from '../types';
import { ChevronLeft, ChevronRight, Loader2, Download, PenLine, Save, Headphones, Play, Square, FileText, Image as ImageIcon, Wand2, Menu, X, Sparkles } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import { generateSpeech, generateImage, refineChapterText } from '../services/gemini';
import { Notification } from './Notification';

interface BookReaderProps {
  outline: BookOutline;
  chapters: ChapterContent[];
  onChapterUpdate?: (chapter: ChapterContent) => void;
  selectedVoice?: string;
  onVoiceChange?: (voice: string) => void;
  onUpdateOutline?: (outline: BookOutline) => void;
}

const DEFAULT_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbxntoxi2DILyS_K3zQlZx9DSUDMupWW9x_p4sfWkCsKzB1Yv38SVSaylfVIX_bAOp4_/exec";

// Audio Cache to prevent re-fetching
const audioCache = new Map<string, AudioBuffer>();

// Helpers for Gemini Audio (PCM)
function decode(base64: string) {
  try {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  } catch (e) {
    console.error("Audio decoding failed", e);
    return new Uint8Array(0);
  }
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number = 24000,
  numChannels: number = 1
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;

  // Create buffer at the SOURCE sample rate (Gemini is 24000Hz)
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

export const BookReader: React.FC<BookReaderProps> = ({ 
  outline, 
  chapters, 
  onChapterUpdate, 
  selectedVoice, 
  onVoiceChange,
  onUpdateOutline
}) => {
  const [currentChapterIndex, setCurrentChapterIndex] = useState(0);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isPlaying, setIsPlaying] = useState(false);
  const [audioLoading, setAudioLoading] = useState(false);
  const [isExporting, setIsExporting] = useState(false);
  const [isExportingDocs, setIsExportingDocs] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editContent, setEditContent] = useState('');
  const [polishInstruction, setPolishInstruction] = useState('');
  const [isPolishing, setIsPolishing] = useState(false);
  const [isCoverGenerating, setIsCoverGenerating] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'error' | 'success'} | null>(null);

  const audioContextRef = useRef<AudioContext | null>(null);
  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  const currentChapter = chapters[currentChapterIndex];

  useEffect(() => {
    stopAudio();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentChapterIndex]);

  const showNotification = (message: string, type: 'error' | 'success' = 'success') => {
    setNotification({ message, type });
    setTimeout(() => setNotification(null), 4000);
  };

  const stopAudio = () => {
    if (audioSourceRef.current) {
      try { audioSourceRef.current.stop(); } catch(e) {}
      audioSourceRef.current = null;
    }
    setIsPlaying(false);
  };

  const playChapterAudio = async () => {
    if (isPlaying) {
      stopAudio();
      return;
    }

    if (!currentChapter?.content) return;

    let silentSource: AudioBufferSourceNode | null = null;

    try {
      if (!audioContextRef.current) {
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
        audioContextRef.current = new AudioContextClass();
      }

      const ctx = audioContextRef.current;

      if (ctx.state === 'suspended') {
        await ctx.resume();
      }

      // Play silent loop to keep mobile audio session alive
      const silentBuffer = ctx.createBuffer(1, 22050, 22050); 
      silentSource = ctx.createBufferSource();
      silentSource.buffer = silentBuffer;
      silentSource.loop = true;
      silentSource.connect(ctx.destination);
      silentSource.start();

    } catch (e) {
      console.error("Audio unlock failed", e);
      showNotification("Could not access audio hardware.", 'error');
      return;
    }

    const cacheKey = `${currentChapter.chapterNumber}-${selectedVoice}-${currentChapter.content.length}`;
    if (audioCache.has(cacheKey)) {
        if (silentSource) (silentSource as AudioBufferSourceNode).stop();
        playBuffer(audioCache.get(cacheKey)!);
        return;
    }

    setAudioLoading(true);

    try {
      const pcmBase64 = await generateSpeech(currentChapter.content.slice(0, 5000), selectedVoice || 'Kore');

      const audioCtx = audioContextRef.current;
      if (!audioCtx) throw new Error("Audio context lost");

      const pcmData = decode(pcmBase64);
      const audioBuffer = await decodeAudioData(pcmData, audioCtx, 24000);

      audioCache.set(cacheKey, audioBuffer);

      if (silentSource) (silentSource as AudioBufferSourceNode).stop();

      playBuffer(audioBuffer);

    } catch (err: any) {
      console.error("Audio playback failed", err);
      if (silentSource) {
        try { (silentSource as AudioBufferSourceNode).stop(); } catch(e) {}
      }
      showNotification("Failed to generate audio. " + (err.message || ""), 'error');
    } finally {
      setAudioLoading(false);
    }
  };

  const playBuffer = (buffer: AudioBuffer) => {
    if (!audioContextRef.current) return;
    const ctx = audioContextRef.current;

    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.connect(ctx.destination);
    source.onended = () => setIsPlaying(false);

    audioSourceRef.current = source;
    source.start();
    setIsPlaying(true);
  };

  const handleDownloadPDF = async () => {
    setIsExporting(true);

    // Create a temporary container to render the clean book structure
    // We position it 'absolute' at 0,0 but behind the app (z-index -9999)
    // This ensures the browser actually paints it (unlike display:none or -9999px left)
    // preventing blank PDF issues on mobile/safari.
    const container = document.createElement('div');
    container.style.position = 'absolute';
    container.style.top = '0';
    container.style.left = '0';
    container.style.width = '800px'; // Fixed width for consistent layout
    container.style.zIndex = '-9999';
    container.style.backgroundColor = '#ffffff';
    document.body.appendChild(container);

    try {
       if (!(window as any).html2pdf) {
         throw new Error("PDF Library not loaded. Please refresh.");
       }

       const styles = `
         <style>
           @import url('https://fonts.googleapis.com/css2?family=Merriweather:ital,wght@0,300;0,400;0,700;1,300&display=swap');
           .pdf-body { font-family: 'Merriweather', serif; color: #000000; line-height: 1.8; padding: 40px; background: white; }
           .pdf-h1 { font-size: 48px; font-weight: 700; margin-bottom: 20px; text-align: center; color: #1e293b; }
           .pdf-h2 { font-size: 32px; font-weight: 700; margin-top: 40px; margin-bottom: 20px; page-break-after: avoid; color: #1e293b; }
           .pdf-p { margin-bottom: 16px; text-align: justify; font-size: 14px; }
           .pdf-cover { max-width: 100%; height: auto; margin: 40px auto; display: block; border: 1px solid #eee; }
           .pdf-title-page { min-height: 900px; display: flex; flex-direction: column; justify-content: center; align-items: center; text-align: center; page-break-after: always; }
           .pdf-chapter { page-break-before: always; margin-top: 40px; }
           .pdf-footer { text-align: center; font-size: 10px; color: #94a3b8; margin-top: 50px; border-top: 1px solid #e2e8f0; padding-top: 10px; }
         </style>
       `;

       const renderMarkdown = (text: string) => {
          // Simple replacement for basic markdown in PDF
          return text
           .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
           .replace(/\*(.*?)\*/g, '<em>$1</em>')
           .replace(/\n\n/g, '</p><p class="pdf-p">')
           .replace(/^# (.*$)/gim, '<h3 class="pdf-h3">$1</h3>')
           .replace(/^## (.*$)/gim, '<h4 class="pdf-h4">$1</h4>');
       };

       const chaptersHtml = chapters.map(chap => `
           <div class="pdf-chapter">
              <div style="text-align: center; margin-bottom: 40px; margin-top: 20px;">
                 <span style="text-transform: uppercase; letter-spacing: 2px; font-size: 12px; border-bottom: 1px solid #000; padding-bottom: 5px;">Chapter ${chap.chapterNumber}</span>
                 <h2 class="pdf-h2">${chap.title}</h2>
              </div>
              <p class="pdf-p">${renderMarkdown(chap.content)}</p>
           </div>
       `).join('');

       container.innerHTML = `
         <div class="pdf-body">
           ${styles}
           <div class="pdf-title-page">
             <h1 class="pdf-h1">${outline.title}</h1>
             <p style="text-transform: uppercase; letter-spacing: 2px; color: #64748b;">A Lore Original</p>
             ${outline.coverImage ? `<img src="data:image/jpeg;base64,${outline.coverImage}" class="pdf-cover" style="max-width: 350px;" />` : ''}
             <p style="font-style: italic; max-width: 600px; margin-top: 40px; color: #475569;">${outline.description}</p>
           </div>
           ${chaptersHtml}
           <div class="pdf-footer">Generated with Lore</div>
         </div>
       `;

       const opt = {
         margin: 0.5,
         filename: `${outline.title.replace(/[^a-z0-9]/gi, '_').toLowerCase()}.pdf`,
         image: { type: 'jpeg', quality: 0.98 },
         // scrollY: 0 is CRITICAL: it forces the canvas to capture from the top of the element
         // ignoring the user's current scroll position which causes blank pages.
         html2canvas: { scale: 2, useCORS: true, letterRendering: true, scrollY: 0 },
         jsPDF: { unit: 'in', format: 'letter', orientation: 'portrait' },
         pagebreak: { mode: ['avoid-all', 'css', 'legacy'] }
       };

       // Small delay to ensure DOM paint
       await new Promise(resolve => setTimeout(resolve, 100));

       await (window as any).html2pdf().set(opt).from(container).save();

       showNotification("PDF downloaded successfully!");

    } catch (e) {
       console.error("PDF Export failed", e);
       showNotification("Visual PDF failed. Try Export to Docs.", 'error');
    } finally {
       if (document.body.contains(container)) {
         document.body.removeChild(container);
       }
       setIsExporting(false);
    }
  };

  const handleExportDocs = async () => {
    setIsExportingDocs(true);

    const scriptUrl = prompt("Enter Google Apps Script URL:", DEFAULT_SCRIPT_URL);
    if (!scriptUrl) {
      setIsExportingDocs(false);
      return;
    }

    try {
      await fetch(scriptUrl, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title: outline.title,
          description: outline.description,
          chapters: chapters.map(c => ({
            chapterNumber: c.chapterNumber,
            title: c.title,
            content: c.content
          }))
        })
      });
      showNotification("Export request sent to Google Docs!");
    } catch (e) {
      console.error(e);
      showNotification("Docs export failed.", 'error');
    } finally {
      setIsExportingDocs(false);
    }
  };

  const startEditing = () => {
    if (!currentChapter) return;
    setEditContent(currentChapter.content);
    setIsEditing(true);
  };

  const saveEditing = () => {
    if (!currentChapter || !onChapterUpdate) return;
    onChapterUpdate({
      ...currentChapter,
      content: editContent
    });
    setIsEditing(false);
    showNotification("Changes saved.");
  };

  const cancelEditing = () => {
    setIsEditing(false);
    setPolishInstruction('');
  };

  const handlePolish = async () => {
    if (!polishInstruction.trim()) return;
    setIsPolishing(true);
    try {
      const polished = await refineChapterText(editContent, polishInstruction);
      setEditContent(polished);
      setPolishInstruction('');
      showNotification("Text refined!");
    } catch (e) {
      console.error(e);
      showNotification("Polish failed.", 'error');
    } finally {
      setIsPolishing(false);
    }
  };

  const handleGenerateCover = async () => {
    if (!onUpdateOutline) return;
    setIsCoverGenerating(true);
    try {
      const prompt = `A professional, high-quality book cover for a book titled "${outline.title}". 
      Description: ${outline.description}. 
      Style: Minimalist, modern, striking typography, best-selling aesthetic.`;

      const base64Image = await generateImage(prompt, '1:1');
      onUpdateOutline({
        ...outline,
        coverImage: base64Image
      });
      showNotification("Cover updated!");
    } catch (e) {
      console.error(e);
      showNotification("Failed to generate cover.", 'error');
    } finally {
      setIsCoverGenerating(false);
    }
  };

  const handleChapterSelect = (idx: number) => {
    setCurrentChapterIndex(idx);
    if (window.innerWidth < 768) {
      setIsSidebarOpen(false);
    }
  };

  return (
    <>
      {notification && (
        <Notification message={notification.message} type={notification.type} onClose={() => setNotification(null)} />
      )}

      <div className="flex flex-col md:flex-row h-[calc(100vh-4rem)] bg-slate-50 relative overflow-hidden">

        {/* Sidebar */}
        <div className={`
            flex-col bg-white border-r border-slate-200 flex-shrink-0 transition-all duration-300 z-30
            ${isSidebarOpen ? 'fixed inset-0 w-full flex md:static md:w-80' : 'hidden md:flex md:w-0 md:overflow-hidden'}
        `}>
          <div className="p-6 border-b border-slate-100 flex-shrink-0 flex justify-between items-start">
             <div className="overflow-hidden">
               <h3 className="font-bold text-slate-900 font-serif mb-1 truncate">{outline.title}</h3>
               <p className="text-xs text-slate-500 uppercase tracking-wider font-semibold">Table of Contents</p>
             </div>
             <button onClick={() => setIsSidebarOpen(false)} className="md:hidden p-1 text-slate-400 hover:text-slate-600">
               <X size={24} />
             </button>
          </div>

          {/* Unified Scrollable Area: Holds both chapters and controls */}
          <div className="flex-1 overflow-y-auto">
             <div className="p-4 space-y-2">
               {chapters.map((chap, idx) => (
                 <button
                   key={chap.chapterNumber}
                   onClick={() => handleChapterSelect(idx)}
                   className={`w-full text-left p-3 rounded-lg text-sm transition-all border ${
                     currentChapterIndex === idx 
                     ? 'bg-blue-50 border-blue-200 text-blue-800 font-bold shadow-sm' 
                     : 'border-transparent hover:bg-slate-50 text-slate-600'
                   }`}
                 >
                   <div className="flex justify-between items-center mb-1">
                      <span className="text-xs opacity-70 uppercase tracking-wide">Chapter {chap.chapterNumber}</span>
                      {chap.isGenerating && <Loader2 size={12} className="animate-spin text-blue-500"/>}
                   </div>
                   <div className="truncate">{chap.title}</div>
                 </button>
               ))}
             </div>

             <div className="p-4 border-t border-slate-100 bg-slate-50/50 space-y-3">
                <div className="bg-white p-3 rounded-lg border border-slate-200 shadow-sm">
                   <div className="flex items-center gap-2 mb-2 text-xs font-bold text-slate-400 uppercase tracking-wider">
                     <Headphones size={12} /> Audiobook
                   </div>
                   <select 
                      value={selectedVoice}
                      onChange={(e) => onVoiceChange && onVoiceChange(e.target.value)}
                      className="w-full text-sm p-2 bg-slate-50 border border-slate-200 rounded mb-2 outline-none focus:border-blue-300"
                   >
                     <option value="Kore">Kore (Balanced)</option>
                     <option value="Puck">Puck (Energetic)</option>
                     <option value="Fenrir">Fenrir (Deep)</option>
                     <option value="Charon">Charon (Calm)</option>
                   </select>
                   <button 
                     onClick={playChapterAudio}
                     disabled={audioLoading || !currentChapter || currentChapter.isGenerating}
                     className={`w-full py-2 rounded-md font-bold text-sm text-white flex items-center justify-center gap-2 transition-all ${isPlaying ? 'bg-slate-800 hover:bg-slate-900' : 'bg-blue-600 hover:bg-blue-500 shadow-sm'}`}
                   >
                     {audioLoading ? <Loader2 size={14} className="animate-spin" /> : isPlaying ? <Square size={14} fill="currentColor" /> : <Play size={14} fill="currentColor" />}
                     {isPlaying ? 'Stop Reading' : 'Read Chapter'}
                   </button>
                </div>

                <div className="bg-white p-4 rounded-lg border border-slate-200 shadow-sm">
                   <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3">Design & Export</div>

                   <div className="mb-4">
                     {outline.coverImage ? (
                       <div className="relative group rounded-md overflow-hidden mb-2 border border-slate-100 shadow-sm">
                          <img src={`data:image/jpeg;base64,${outline.coverImage}`} alt="Cover" className="w-full h-full object-cover aspect-square" />
                          <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                             <button onClick={handleGenerateCover} className="text-white text-xs font-bold flex items-center gap-1 hover:underline">
                                <ImageIcon size={12} /> Regenerate
                             </button>
                          </div>
                       </div>
                     ) : (
                       <button 
                         onClick={handleGenerateCover}
                         disabled={isCoverGenerating}
                         className="w-full py-2 px-3 bg-purple-50 hover:bg-purple-100 text-purple-700 rounded-md text-xs font-bold flex items-center justify-center gap-2 transition-all mb-2"
                       >
                         {isCoverGenerating ? <Loader2 size={12} className="animate-spin" /> : <Sparkles size={12} />}
                         Generate Full Cover
                       </button>
                     )}
                   </div>

                   <button 
                     onClick={handleDownloadPDF}
                     disabled={isExporting}
                     className="w-full flex items-center gap-2 text-slate-600 hover:text-blue-700 hover:bg-slate-50 p-2 rounded-md text-sm font-medium transition-colors mb-1"
                   >
                     {isExporting ? <Loader2 size={16} className="animate-spin" /> : <Download size={16} />}
                     Download E-Book (PDF)
                   </button>
                   <button 
                     onClick={handleExportDocs}
                     disabled={isExportingDocs}
                     className="w-full flex items-center gap-2 text-slate-600 hover:text-blue-700 hover:bg-slate-50 p-2 rounded-md text-sm font-medium transition-colors"
                   >
                     {isExportingDocs ? <Loader2 size={16} className="animate-spin" /> : <FileText size={16} />}
                     Export to Docs
                   </button>
                </div>
             </div>
          </div>

        </div>

        {/* Reader Content */}
        <div className="flex-1 flex flex-col h-full overflow-hidden bg-slate-50 relative w-full">

           <div className="md:hidden h-14 bg-white border-b border-slate-200 flex items-center px-4 shrink-0 justify-between">
              <button onClick={() => setIsSidebarOpen(true)} className="p-2 -ml-2 text-slate-600 hover:bg-slate-100 rounded-lg">
                 <Menu size={24} />
              </button>
              <span className="font-serif font-bold text-slate-900 truncate max-w-[200px]">
                 {currentChapter ? `Ch ${currentChapter.chapterNumber}: ${currentChapter.title}` : 'Reader'}
              </span>
              <div className="w-8"></div>
           </div>

           <div className="hidden md:block absolute top-4 left-4 z-20">
              <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 bg-white shadow-md rounded-lg border border-slate-200 text-slate-600 hover:text-blue-600 transition-colors">
                 {isSidebarOpen ? <ChevronLeft size={20} /> : <ChevronRight size={20} />}
              </button>
           </div>

           <div className="flex-1 overflow-y-auto p-4 md:p-12 scroll-smooth">
             <div className="max-w-3xl mx-auto bg-white shadow-xl shadow-slate-200/50 min-h-[80vh] p-6 md:p-16 rounded-xl relative border border-slate-100">

                <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-blue-100 via-blue-50 to-blue-100 opacity-50"></div>

                {!currentChapter ? (
                  <div className="flex flex-col items-center justify-center h-64 text-slate-400">
                    <Loader2 size={40} className="animate-spin mb-4 text-blue-200" />
                    <p>Loading Manuscript...</p>
                  </div>
                ) : (
                  <>
                    <div className="mb-8 pb-8 border-b border-slate-100">
                       <span className="text-xs font-bold tracking-[0.2em] text-slate-400 uppercase mb-2 block text-center">Chapter {currentChapter.chapterNumber}</span>
                       <h2 className="text-2xl md:text-4xl font-serif font-bold text-slate-900 text-center leading-tight">{currentChapter.title}</h2>
                    </div>

                    {isEditing ? (
                       <div className="animate-in fade-in">
                          <textarea 
                             value={editContent}
                             onChange={(e) => setEditContent(e.target.value)}
                             className="w-full h-[60vh] p-4 font-serif text-lg leading-relaxed text-slate-800 border-2 border-blue-100 rounded-lg outline-none focus:ring-2 focus:ring-blue-200 resize-y mb-4"
                          />

                          <div className="bg-blue-50 p-4 rounded-xl border border-blue-100 mb-6 flex gap-3 items-center">
                             <div className="bg-blue-200 p-2 rounded-full text-blue-700"><Wand2 size={16} /></div>
                             <div className="flex-1">
                                <input 
                                  value={polishInstruction}
                                  onChange={(e) => setPolishInstruction(e.target.value)}
                                  placeholder="Ask AI to polish (e.g., 'Make it more dramatic')"
                                  className="w-full bg-white border border-blue-200 rounded px-3 py-2 text-sm outline-none focus:border-blue-400"
                                  onKeyDown={(e) => e.key === 'Enter' && handlePolish()}
                                />
                             </div>
                             <button 
                               onClick={handlePolish}
                               disabled={isPolishing || !polishInstruction.trim()}
                               className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white text-sm font-bold rounded-lg transition-colors disabled:opacity-50"
                             >
                               {isPolishing ? <Loader2 size={16} className="animate-spin" /> : 'Refine'}
                             </button>
                          </div>

                          <div className="flex justify-end gap-3 sticky bottom-0 bg-white pt-4 border-t border-slate-100">
                             <button onClick={cancelEditing} className="px-5 py-2.5 text-slate-600 font-bold text-sm hover:bg-slate-100 rounded-lg">Cancel</button>
                             <button onClick={saveEditing} className="px-5 py-2.5 bg-emerald-600 hover:bg-emerald-500 text-white font-bold text-sm rounded-lg shadow-lg shadow-emerald-200 flex items-center gap-2">
                                <Save size={16} /> Save Changes
                             </button>
                          </div>
                       </div>
                    ) : (
                      <div className="prose prose-lg prose-slate font-serif max-w-none prose-headings:font-sans prose-headings:font-bold prose-p:leading-loose text-slate-800">
                         {currentChapter.isGenerating ? (
                           <div className="space-y-4 animate-pulse">
                              <div className="h-4 bg-slate-100 rounded w-full"></div>
                              <div className="h-4 bg-slate-100 rounded w-11/12"></div>
                              <div className="h-4 bg-slate-100 rounded w-full"></div>
                              <div className="py-8 text-center text-slate-400 text-sm font-sans flex items-center justify-center gap-2">
                                <Loader2 size={16} className="animate-spin" /> Writing in progress...
                              </div>
                           </div>
                         ) : (
                           <div className="relative group min-h-[200px]">
                              <ReactMarkdown>{currentChapter.content}</ReactMarkdown>
                              <button 
                                onClick={startEditing}
                                className="absolute top-0 right-0 p-2 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-lg opacity-0 group-hover:opacity-100 transition-all"
                                title="Edit Text"
                              >
                                <PenLine size={20} />
                              </button>
                           </div>
                         )}
                      </div>
                    )}
                  </>
                )}
             </div>

             <div className="max-w-3xl mx-auto mt-8 flex justify-between items-center text-sm font-medium text-slate-500 pb-24 md:pb-12 px-4">
                <button 
                  onClick={() => setCurrentChapterIndex(prev => Math.max(0, prev - 1))}
                  disabled={currentChapterIndex === 0}
                  className="flex items-center gap-2 hover:text-blue-600 disabled:opacity-30 disabled:hover:text-slate-500 transition-colors px-4 py-2 hover:bg-white rounded-full"
                >
                  <ChevronLeft size={16} /> Previous
                </button>
                <span>{currentChapterIndex + 1} / {chapters.length}</span>
                <button 
                  onClick={() => setCurrentChapterIndex(prev => Math.min(chapters.length - 1, prev + 1))}
                  disabled={currentChapterIndex === chapters.length - 1}
                  className="flex items-center gap-2 hover:text-blue-600 disabled:opacity-30 disabled:hover:text-slate-500 transition-colors px-4 py-2 hover:bg-white rounded-full"
                >
                  Next <ChevronRight size={16} />
                </button>
             </div>
           </div>
        </div>
      </div>
    </>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { ChapterContent, BookOutline } from '../types';
import { ChevronLeft, ChevronRight, Loader2, Download, PenLine, Save, Headphones, Play, Square, FileText, Image as ImageIcon, Wand2, Menu, X, Sparkles, Printer } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import { generateSpeech, generateImage, refineChapterText } from '../services/gemini';
import { Notification } from './Notification';

interface BookReaderProps {
  outline: BookOutline;
  chapters: ChapterContent[];
  onChapterUpdate?: (chapter: ChapterContent) => void;
  selectedVoice?: string;
  onVoiceChange?: (voice: string) => void;
  onUpdateOutline?: (outline: BookOutline) => void;
}

const DEFAULT_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbxntoxi2DILyS_K3zQlZx9DSUDMupWW9x_p4sfWkCsKzB1Yv38SVSaylfVIX_bAOp4_/exec";

// Audio Cache to prevent re-fetching
const audioCache = new Map<string, AudioBuffer>();

// Helpers for Gemini Audio (PCM)
function decode(base64: string) {
  try {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  } catch (e) {
    console.error("Audio decoding failed", e);
    return new Uint8Array(0);
  }
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number = 24000,
  numChannels: number = 1
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;

  // Create buffer at the SOURCE sample rate (Gemini is 24000Hz)
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

export const BookReader: React.FC<BookReaderProps> = ({ 
  outline, 
  chapters, 
  onChapterUpdate, 
  selectedVoice, 
  onVoiceChange,
  onUpdateOutline
}) => {
  const [currentChapterIndex, setCurrentChapterIndex] = useState(0);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isPlaying, setIsPlaying] = useState(false);
  const [audioLoading, setAudioLoading] = useState(false);
  const [isExportingDocs, setIsExportingDocs] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editContent, setEditContent] = useState('');
  const [polishInstruction, setPolishInstruction] = useState('');
  const [isPolishing, setIsPolishing] = useState(false);
  const [isCoverGenerating, setIsCoverGenerating] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'error' | 'success'} | null>(null);

  // PDF Preview State
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);

  const audioContextRef = useRef<AudioContext | null>(null);
  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  const currentChapter = chapters[currentChapterIndex];

  useEffect(() => {
    stopAudio();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentChapterIndex]);

  const showNotification = (message: string, type: 'error' | 'success' = 'success') => {
    setNotification({ message, type });
    setTimeout(() => setNotification(null), 4000);
  };

  const stopAudio = () => {
    if (audioSourceRef.current) {
      try { audioSourceRef.current.stop(); } catch(e) {}
      audioSourceRef.current = null;
    }
    setIsPlaying(false);
  };

  const playChapterAudio = async () => {
    if (isPlaying) {
      stopAudio();
      return;
    }

    if (!currentChapter?.content) return;

    let silentSource: AudioBufferSourceNode | null = null;

    try {
      if (!audioContextRef.current) {
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
        audioContextRef.current = new AudioContextClass();
      }

      const ctx = audioContextRef.current;

      if (ctx.state === 'suspended') {
        await ctx.resume();
      }

      // Play silent loop to keep mobile audio session alive
      const silentBuffer = ctx.createBuffer(1, 22050, 22050); 
      silentSource = ctx.createBufferSource();
      silentSource.buffer = silentBuffer;
      silentSource.loop = true;
      silentSource.connect(ctx.destination);
      silentSource.start();

    } catch (e) {
      console.error("Audio unlock failed", e);
      showNotification("Could not access audio hardware.", 'error');
      return;
    }

    const cacheKey = `${currentChapter.chapterNumber}-${selectedVoice}-${currentChapter.content.length}`;
    if (audioCache.has(cacheKey)) {
        if (silentSource) (silentSource as AudioBufferSourceNode).stop();
        playBuffer(audioCache.get(cacheKey)!);
        return;
    }

    setAudioLoading(true);

    try {
      const pcmBase64 = await generateSpeech(currentChapter.content.slice(0, 5000), selectedVoice || 'Kore');

      const audioCtx = audioContextRef.current;
      if (!audioCtx) throw new Error("Audio context lost");

      const pcmData = decode(pcmBase64);
      const audioBuffer = await decodeAudioData(pcmData, audioCtx, 24000);

      audioCache.set(cacheKey, audioBuffer);

      if (silentSource) (silentSource as AudioBufferSourceNode).stop();

      playBuffer(audioBuffer);

    } catch (err: any) {
      console.error("Audio playback failed", err);
      if (silentSource) {
        try { (silentSource as AudioBufferSourceNode).stop(); } catch(e) {}
      }
      showNotification("Failed to generate audio. " + (err.message || ""), 'error');
    } finally {
      setAudioLoading(false);
    }
  };

  const playBuffer = (buffer: AudioBuffer) => {
    if (!audioContextRef.current) return;
    const ctx = audioContextRef.current;

    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.connect(ctx.destination);
    source.onended = () => setIsPlaying(false);

    audioSourceRef.current = source;
    source.start();
    setIsPlaying(true);
  };

  const handlePrint = () => {
    window.print();
  };

  const handleExportDocs = async () => {
    setIsExportingDocs(true);

    const scriptUrl = prompt("Enter Google Apps Script URL:", DEFAULT_SCRIPT_URL);
    if (!scriptUrl) {
      setIsExportingDocs(false);
      return;
    }

    try {
      await fetch(scriptUrl, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title: outline.title,
          description: outline.description,
          chapters: chapters.map(c => ({
            chapterNumber: c.chapterNumber,
            title: c.title,
            content: c.content
          }))
        })
      });
      showNotification("Export request sent to Google Docs!");
    } catch (e) {
      console.error(e);
      showNotification("Docs export failed.", 'error');
    } finally {
      setIsExportingDocs(false);
    }
  };

  const startEditing = () => {
    if (!currentChapter) return;
    setEditContent(currentChapter.content);
    setIsEditing(true);
  };

  const saveEditing = () => {
    if (!currentChapter || !onChapterUpdate) return;
    onChapterUpdate({
      ...currentChapter,
      content: editContent
    });
    setIsEditing(false);
    showNotification("Changes saved.");
  };

  const cancelEditing = () => {
    setIsEditing(false);
    setPolishInstruction('');
  };

  const handlePolish = async () => {
    if (!polishInstruction.trim()) return;
    setIsPolishing(true);
    try {
      const polished = await refineChapterText(editContent, polishInstruction);
      setEditContent(polished);
      setPolishInstruction('');
      showNotification("Text refined!");
    } catch (e) {
      console.error(e);
      showNotification("Polish failed.", 'error');
    } finally {
      setIsPolishing(false);
    }
  };

  const handleGenerateCover = async () => {
    if (!onUpdateOutline) return;
    setIsCoverGenerating(true);
    try {
      const prompt = `A professional, high-quality book cover for a book titled "${outline.title}". 
      Description: ${outline.description}. 
      Style: Minimalist, modern, striking typography, best-selling aesthetic.`;

      const base64Image = await generateImage(prompt, '1:1');
      onUpdateOutline({
        ...outline,
        coverImage: base64Image
      });
      showNotification("Cover updated!");
    } catch (e) {
      console.error(e);
      showNotification("Failed to generate cover.", 'error');
    } finally {
      setIsCoverGenerating(false);
    }
  };

  const handleChapterSelect = (idx: number) => {
    setCurrentChapterIndex(idx);
    if (window.innerWidth < 768) {
      setIsSidebarOpen(false);
    }
  };

  // --- PDF Preview Mode ---
  if (isPreviewOpen) {
    return (
      <div className="fixed inset-0 z-50 bg-white overflow-y-auto">
        <style>
          {`
            @media print {
              .no-print { display: none !important; }
              body { background: white; color: black; }
              @page { margin: 2cm; size: auto; }
              .page-break { page-break-before: always; }
            }
          `}
        </style>

        {/* Print Toolbar */}
        <div className="sticky top-0 z-50 bg-slate-900 text-white p-4 flex justify-between items-center shadow-lg no-print">
           <div className="flex items-center gap-4">
              <button onClick={() => setIsPreviewOpen(false)} className="flex items-center gap-2 text-sm font-bold text-slate-300 hover:text-white">
                 <ChevronLeft size={16} /> Back to Editor
              </button>
              <div className="h-4 w-px bg-slate-700"></div>
              <span className="font-serif font-bold">{outline.title} (Preview)</span>
           </div>
           <button 
             onClick={handlePrint}
             className="bg-blue-600 hover:bg-blue-500 text-white px-6 py-2 rounded-md font-bold text-sm flex items-center gap-2 shadow-sm"
           >
             <Printer size={16} /> Print / Save as PDF
           </button>
        </div>

        {/* Book Content (Print Layout) */}
        <div className="max-w-[800px] mx-auto bg-white p-12 md:p-24 min-h-screen shadow-2xl md:my-12 print:shadow-none print:p-0 print:m-0">

           {/* Title Page */}
           <div className="flex flex-col items-center justify-center min-h-[800px] text-center page-break mb-24">
              <h1 className="text-5xl md:text-6xl font-serif font-bold text-slate-900 mb-6 leading-tight">{outline.title}</h1>
              <div className="w-16 h-1 bg-slate-900 mb-8"></div>
              <p className="text-sm uppercase tracking-[0.3em] text-slate-500 mb-12">A Lore Original</p>

              {outline.coverImage && (
                <img src={`data:image/jpeg;base64,${outline.coverImage}`} className="w-64 h-64 object-cover shadow-lg mb-12 print:shadow-none border border-slate-100" />
              )}

              <p className="max-w-md text-slate-600 italic font-serif leading-relaxed">{outline.description}</p>
           </div>

           {/* Chapters */}
           {chapters.map((chapter) => (
             <div key={chapter.chapterNumber} className="page-break mt-12">
                <div className="text-center mb-12 mt-8">
                   <span className="text-xs font-bold uppercase tracking-widest border-b border-slate-300 pb-2 mb-4 inline-block">Chapter {chapter.chapterNumber}</span>
                   <h2 className="text-3xl font-serif font-bold text-slate-900">{chapter.title}</h2>
                </div>

                <div className="prose prose-lg prose-slate font-serif max-w-none text-justify leading-loose">
                   <ReactMarkdown>{chapter.content}</ReactMarkdown>
                </div>
             </div>
           ))}

           <div className="text-center mt-24 pt-12 border-t border-slate-100 text-xs text-slate-400">
              Generated with Lore
           </div>
        </div>
      </div>
    );
  }

  // --- Normal Editor Mode ---
  return (
    <>
      {notification && (
        <Notification message={notification.message} type={notification.type} onClose={() => setNotification(null)} />
      )}

      <div className="flex flex-col md:flex-row h-[calc(100vh-4rem)] bg-slate-50 relative overflow-hidden">

        {/* Sidebar */}
        <div className={`
            flex-col bg-white border-r border-slate-200 flex-shrink-0 transition-all duration-300 z-30
            ${isSidebarOpen ? 'fixed inset-0 w-full flex md:static md:w-80' : 'hidden md:flex md:w-0 md:overflow-hidden'}
        `}>
          <div className="p-6 border-b border-slate-100 flex-shrink-0 flex justify-between items-start">
             <div className="overflow-hidden">
               <h3 className="font-bold text-slate-900 font-serif mb-1 truncate">{outline.title}</h3>
               <p className="text-xs text-slate-500 uppercase tracking-wider font-semibold">Table of Contents</p>
             </div>
             <button onClick={() => setIsSidebarOpen(false)} className="md:hidden p-1 text-slate-400 hover:text-slate-600">
               <X size={24} />
             </button>
          </div>

          {/* Unified Scrollable Area: Holds both chapters and controls */}
          <div className="flex-1 overflow-y-auto">
             <div className="p-4 space-y-2">
               {chapters.map((chap, idx) => (
                 <button
                   key={chap.chapterNumber}
                   onClick={() => handleChapterSelect(idx)}
                   className={`w-full text-left p-3 rounded-lg text-sm transition-all border ${
                     currentChapterIndex === idx 
                     ? 'bg-blue-50 border-blue-200 text-blue-800 font-bold shadow-sm' 
                     : 'border-transparent hover:bg-slate-50 text-slate-600'
                   }`}
                 >
                   <div className="flex justify-between items-center mb-1">
                      <span className="text-xs opacity-70 uppercase tracking-wide">Chapter {chap.chapterNumber}</span>
                      {chap.isGenerating && <Loader2 size={12} className="animate-spin text-blue-500"/>}
                   </div>
                   <div className="truncate">{chap.title}</div>
                 </button>
               ))}
             </div>

             <div className="p-4 border-t border-slate-100 bg-slate-50/50 space-y-3">
                <div className="bg-white p-3 rounded-lg border border-slate-200 shadow-sm">
                   <div className="flex items-center gap-2 mb-2 text-xs font-bold text-slate-400 uppercase tracking-wider">
                     <Headphones size={12} /> Audiobook
                   </div>
                   <select 
                      value={selectedVoice}
                      onChange={(e) => onVoiceChange && onVoiceChange(e.target.value)}
                      className="w-full text-sm p-2 bg-slate-50 border border-slate-200 rounded mb-2 outline-none focus:border-blue-300"
                   >
                     <option value="Kore">Kore (Balanced)</option>
                     <option value="Puck">Puck (Energetic)</option>
                     <option value="Fenrir">Fenrir (Deep)</option>
                     <option value="Charon">Charon (Calm)</option>
                   </select>
                   <button 
                     onClick={playChapterAudio}
                     disabled={audioLoading || !currentChapter || currentChapter.isGenerating}
                     className={`w-full py-2 rounded-md font-bold text-sm text-white flex items-center justify-center gap-2 transition-all ${isPlaying ? 'bg-slate-800 hover:bg-slate-900' : 'bg-blue-600 hover:bg-blue-500 shadow-sm'}`}
                   >
                     {audioLoading ? <Loader2 size={14} className="animate-spin" /> : isPlaying ? <Square size={14} fill="currentColor" /> : <Play size={14} fill="currentColor" />}
                     {isPlaying ? 'Stop Reading' : 'Read Chapter'}
                   </button>
                </div>

                <div className="bg-white p-4 rounded-lg border border-slate-200 shadow-sm">
                   <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3">Design & Export</div>

                   <div className="mb-4">
                     {outline.coverImage ? (
                       <div className="relative group rounded-md overflow-hidden mb-2 border border-slate-100 shadow-sm">
                          <img src={`data:image/jpeg;base64,${outline.coverImage}`} alt="Cover" className="w-full h-full object-cover aspect-square" />
                          <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                             <button onClick={handleGenerateCover} className="text-white text-xs font-bold flex items-center gap-1 hover:underline">
                                <ImageIcon size={12} /> Regenerate
                             </button>
                          </div>
                       </div>
                     ) : (
                       <button 
                         onClick={handleGenerateCover}
                         disabled={isCoverGenerating}
                         className="w-full py-2 px-3 bg-purple-50 hover:bg-purple-100 text-purple-700 rounded-md text-xs font-bold flex items-center justify-center gap-2 transition-all mb-2"
                       >
                         {isCoverGenerating ? <Loader2 size={12} className="animate-spin" /> : <Sparkles size={12} />}
                         Generate Full Cover
                       </button>
                     )}
                   </div>

                   <button 
                     onClick={() => setIsPreviewOpen(true)}
                     className="w-full flex items-center gap-2 text-slate-600 hover:text-blue-700 hover:bg-slate-50 p-2 rounded-md text-sm font-medium transition-colors mb-1"
                   >
                     <Download size={16} />
                     Download E-Book (PDF)
                   </button>
                   <button 
                     onClick={handleExportDocs}
                     disabled={isExportingDocs}
                     className="w-full flex items-center gap-2 text-slate-600 hover:text-blue-700 hover:bg-slate-50 p-2 rounded-md text-sm font-medium transition-colors"
                   >
                     {isExportingDocs ? <Loader2 size={16} className="animate-spin" /> : <FileText size={16} />}
                     Export to Docs
                   </button>
                </div>
             </div>
          </div>

        </div>

        {/* Reader Content */}
        <div className="flex-1 flex flex-col h-full overflow-hidden bg-slate-50 relative w-full">

           <div className="md:hidden h-14 bg-white border-b border-slate-200 flex items-center px-4 shrink-0 justify-between">
              <button onClick={() => setIsSidebarOpen(true)} className="p-2 -ml-2 text-slate-600 hover:bg-slate-100 rounded-lg">
                 <Menu size={24} />
              </button>
              <span className="font-serif font-bold text-slate-900 truncate max-w-[200px]">
                 {currentChapter ? `Ch ${currentChapter.chapterNumber}: ${currentChapter.title}` : 'Reader'}
              </span>
              <div className="w-8"></div>
           </div>

           <div className="hidden md:block absolute top-4 left-4 z-20">
              <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 bg-white shadow-md rounded-lg border border-slate-200 text-slate-600 hover:text-blue-600 transition-colors">
                 {isSidebarOpen ? <ChevronLeft size={20} /> : <ChevronRight size={20} />}
              </button>
           </div>

           <div className="flex-1 overflow-y-auto p-4 md:p-12 scroll-smooth">
             <div className="max-w-3xl mx-auto bg-white shadow-xl shadow-slate-200/50 min-h-[80vh] p-6 md:p-16 rounded-xl relative border border-slate-100">

                <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-blue-100 via-blue-50 to-blue-100 opacity-50"></div>

                {!currentChapter ? (
                  <div className="flex flex-col items-center justify-center h-64 text-slate-400">
                    <Loader2 size={40} className="animate-spin mb-4 text-blue-200" />
                    <p>Loading Manuscript...</p>
                  </div>
                ) : (
                  <>
                    <div className="mb-8 pb-8 border-b border-slate-100">
                       <span className="text-xs font-bold tracking-[0.2em] text-slate-400 uppercase mb-2 block text-center">Chapter {currentChapter.chapterNumber}</span>
                       <h2 className="text-2xl md:text-4xl font-serif font-bold text-slate-900 text-center leading-tight">{currentChapter.title}</h2>
                    </div>

                    {isEditing ? (
                       <div className="animate-in fade-in">
                          <textarea 
                             value={editContent}
                             onChange={(e) => setEditContent(e.target.value)}
                             className="w-full h-[60vh] p-4 font-serif text-lg leading-relaxed text-slate-800 border-2 border-blue-100 rounded-lg outline-none focus:ring-2 focus:ring-blue-200 resize-y mb-4"
                          />

                          <div className="bg-blue-50 p-4 rounded-xl border border-blue-100 mb-6 flex gap-3 items-center">
                             <div className="bg-blue-200 p-2 rounded-full text-blue-700"><Wand2 size={16} /></div>
                             <div className="flex-1">
                                <input 
                                  value={polishInstruction}
                                  onChange={(e) => setPolishInstruction(e.target.value)}
                                  placeholder="Ask AI to polish (e.g., 'Make it more dramatic')"
                                  className="w-full bg-white border border-blue-200 rounded px-3 py-2 text-sm outline-none focus:border-blue-400"
                                  onKeyDown={(e) => e.key === 'Enter' && handlePolish()}
                                />
                             </div>
                             <button 
                               onClick={handlePolish}
                               disabled={isPolishing || !polishInstruction.trim()}
                               className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white text-sm font-bold rounded-lg transition-colors disabled:opacity-50"
                             >
                               {isPolishing ? <Loader2 size={16} className="animate-spin" /> : 'Refine'}
                             </button>
                          </div>

                          <div className="flex justify-end gap-3 sticky bottom-0 bg-white pt-4 border-t border-slate-100">
                             <button onClick={cancelEditing} className="px-5 py-2.5 text-slate-600 font-bold text-sm hover:bg-slate-100 rounded-lg">Cancel</button>
                             <button onClick={saveEditing} className="px-5 py-2.5 bg-emerald-600 hover:bg-emerald-500 text-white font-bold text-sm rounded-lg shadow-lg shadow-emerald-200 flex items-center gap-2">
                                <Save size={16} /> Save Changes
                             </button>
                          </div>
                       </div>
                    ) : (
                      <div className="prose prose-lg prose-slate font-serif max-w-none prose-headings:font-sans prose-headings:font-bold prose-p:leading-loose text-slate-800">
                         {currentChapter.isGenerating ? (
                           <div className="space-y-4 animate-pulse">
                              <div className="h-4 bg-slate-100 rounded w-full"></div>
                              <div className="h-4 bg-slate-100 rounded w-11/12"></div>
                              <div className="h-4 bg-slate-100 rounded w-full"></div>
                              <div className="py-8 text-center text-slate-400 text-sm font-sans flex items-center justify-center gap-2">
                                <Loader2 size={16} className="animate-spin" /> Writing in progress...
                              </div>
                           </div>
                         ) : (
                           <div className="relative group min-h-[200px]">
                              <ReactMarkdown>{currentChapter.content}</ReactMarkdown>
                              <button 
                                onClick={startEditing}
                                className="absolute top-0 right-0 p-2 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-lg opacity-0 group-hover:opacity-100 transition-all"
                                title="Edit Text"
                              >
                                <PenLine size={20} />
                              </button>
                           </div>
                         )}
                      </div>
                    )}
                  </>
                )}
             </div>

             <div className="max-w-3xl mx-auto mt-8 flex justify-between items-center text-sm font-medium text-slate-500 pb-24 md:pb-12 px-4">
                <button 
                  onClick={() => setCurrentChapterIndex(prev => Math.max(0, prev - 1))}
                  disabled={currentChapterIndex === 0}
                  className="flex items-center gap-2 hover:text-blue-600 disabled:opacity-30 disabled:hover:text-slate-500 transition-colors px-4 py-2 hover:bg-white rounded-full"
                >
                  <ChevronLeft size={16} /> Previous
                </button>
                <span>{currentChapterIndex + 1} / {chapters.length}</span>
                <button 
                  onClick={() => setCurrentChapterIndex(prev => Math.min(chapters.length - 1, prev + 1))}
                  disabled={currentChapterIndex === chapters.length - 1}
                  className="flex items-center gap-2 hover:text-blue-600 disabled:opacity-30 disabled:hover:text-slate-500 transition-colors px-4 py-2 hover:bg-white rounded-full"
                >
                  Next <ChevronRight size={16} />
                </button>
             </div>
           </div>
        </div>
      </div>
    </>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { ChapterContent, BookOutline } from '../types';
import { ChevronLeft, ChevronRight, Loader2, Download, PenLine, Save, Headphones, Play, Square, FileText, Image as ImageIcon, Wand2, Menu, X, Sparkles, Printer } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import { generateSpeech, generateImage, refineChapterText } from '../services/gemini';
import { Notification } from './Notification';

interface BookReaderProps {
  outline: BookOutline;
  chapters: ChapterContent[];
  onChapterUpdate?: (chapter: ChapterContent) => void;
  selectedVoice?: string;
  onVoiceChange?: (voice: string) => void;
  onUpdateOutline?: (outline: BookOutline) => void;
}

const DEFAULT_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbxntoxi2DILyS_K3zQlZx9DSUDMupWW9x_p4sfWkCsKzB1Yv38SVSaylfVIX_bAOp4_/exec";

// Audio Cache to prevent re-fetching
const audioCache = new Map<string, AudioBuffer>();

// Helpers for Gemini Audio (PCM)
function decode(base64: string) {
  try {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  } catch (e) {
    console.error("Audio decoding failed", e);
    return new Uint8Array(0);
  }
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number = 24000,
  numChannels: number = 1
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;

  // Create buffer at the SOURCE sample rate (Gemini is 24000Hz)
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

export const BookReader: React.FC<BookReaderProps> = ({ 
  outline, 
  chapters, 
  onChapterUpdate, 
  selectedVoice, 
  onVoiceChange,
  onUpdateOutline
}) => {
  const [currentChapterIndex, setCurrentChapterIndex] = useState(0);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isPlaying, setIsPlaying] = useState(false);
  const [audioLoading, setAudioLoading] = useState(false);
  const [isExportingDocs, setIsExportingDocs] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editContent, setEditContent] = useState('');
  const [polishInstruction, setPolishInstruction] = useState('');
  const [isPolishing, setIsPolishing] = useState(false);
  const [isCoverGenerating, setIsCoverGenerating] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'error' | 'success'} | null>(null);

  // PDF Preview State
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);

  const audioContextRef = useRef<AudioContext | null>(null);
  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  const currentChapter = chapters[currentChapterIndex];

  useEffect(() => {
    stopAudio();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentChapterIndex]);

  const showNotification = (message: string, type: 'error' | 'success' = 'success') => {
    setNotification({ message, type });
    setTimeout(() => setNotification(null), 4000);
  };

  const stopAudio = () => {
    if (audioSourceRef.current) {
      try { audioSourceRef.current.stop(); } catch(e) {}
      audioSourceRef.current = null;
    }
    setIsPlaying(false);
  };

  const playChapterAudio = async () => {
    if (isPlaying) {
      stopAudio();
      return;
    }

    if (!currentChapter?.content) return;

    let silentSource: AudioBufferSourceNode | null = null;

    try {
      if (!audioContextRef.current) {
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
        audioContextRef.current = new AudioContextClass();
      }

      const ctx = audioContextRef.current;

      if (ctx.state === 'suspended') {
        await ctx.resume();
      }

      // Play silent loop to keep mobile audio session alive
      const silentBuffer = ctx.createBuffer(1, 22050, 22050); 
      silentSource = ctx.createBufferSource();
      silentSource.buffer = silentBuffer;
      silentSource.loop = true;
      silentSource.connect(ctx.destination);
      silentSource.start();

    } catch (e) {
      console.error("Audio unlock failed", e);
      showNotification("Could not access audio hardware.", 'error');
      return;
    }

    const cacheKey = `${currentChapter.chapterNumber}-${selectedVoice}-${currentChapter.content.length}`;
    if (audioCache.has(cacheKey)) {
        if (silentSource) (silentSource as AudioBufferSourceNode).stop();
        playBuffer(audioCache.get(cacheKey)!);
        return;
    }

    setAudioLoading(true);

    try {
      const pcmBase64 = await generateSpeech(currentChapter.content.slice(0, 5000), selectedVoice || 'Kore');

      const audioCtx = audioContextRef.current;
      if (!audioCtx) throw new Error("Audio context lost");

      const pcmData = decode(pcmBase64);
      const audioBuffer = await decodeAudioData(pcmData, audioCtx, 24000);

      audioCache.set(cacheKey, audioBuffer);

      if (silentSource) (silentSource as AudioBufferSourceNode).stop();

      playBuffer(audioBuffer);

    } catch (err: any) {
      console.error("Audio playback failed", err);
      if (silentSource) {
        try { (silentSource as AudioBufferSourceNode).stop(); } catch(e) {}
      }
      showNotification("Failed to generate audio. " + (err.message || ""), 'error');
    } finally {
      setAudioLoading(false);
    }
  };

  const playBuffer = (buffer: AudioBuffer) => {
    if (!audioContextRef.current) return;
    const ctx = audioContextRef.current;

    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.connect(ctx.destination);
    source.onended = () => setIsPlaying(false);

    audioSourceRef.current = source;
    source.start();
    setIsPlaying(true);
  };

  const handlePrint = () => {
    window.print();
  };

  const handleExportDocs = async () => {
    setIsExportingDocs(true);

    const scriptUrl = prompt("Enter Google Apps Script URL:", DEFAULT_SCRIPT_URL);
    if (!scriptUrl) {
      setIsExportingDocs(false);
      return;
    }

    try {
      await fetch(scriptUrl, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title: outline.title,
          description: outline.description,
          chapters: chapters.map(c => ({
            chapterNumber: c.chapterNumber,
            title: c.title,
            content: c.content
          }))
        })
      });
      showNotification("Export request sent to Google Docs!");
    } catch (e) {
      console.error(e);
      showNotification("Docs export failed.", 'error');
    } finally {
      setIsExportingDocs(false);
    }
  };

  const startEditing = () => {
    if (!currentChapter) return;
    setEditContent(currentChapter.content);
    setIsEditing(true);
  };

  const saveEditing = () => {
    if (!currentChapter || !onChapterUpdate) return;
    onChapterUpdate({
      ...currentChapter,
      content: editContent
    });
    setIsEditing(false);
    showNotification("Changes saved.");
  };

  const cancelEditing = () => {
    setIsEditing(false);
    setPolishInstruction('');
  };

  const handlePolish = async () => {
    if (!polishInstruction.trim()) return;
    setIsPolishing(true);
    try {
      const polished = await refineChapterText(editContent, polishInstruction);
      setEditContent(polished);
      setPolishInstruction('');
      showNotification("Text refined!");
    } catch (e) {
      console.error(e);
      showNotification("Polish failed.", 'error');
    } finally {
      setIsPolishing(false);
    }
  };

  const handleGenerateCover = async () => {
    if (!onUpdateOutline) return;
    setIsCoverGenerating(true);
    try {
      const prompt = `A professional, high-quality book cover for a book titled "${outline.title}". 
      Description: ${outline.description}. 
      Style: Minimalist, modern, striking typography, best-selling aesthetic.`;

      const base64Image = await generateImage(prompt, '1:1');
      onUpdateOutline({
        ...outline,
        coverImage: base64Image
      });
      showNotification("Cover updated!");
    } catch (e) {
      console.error(e);
      showNotification("Failed to generate cover.", 'error');
    } finally {
      setIsCoverGenerating(false);
    }
  };

  const handleChapterSelect = (idx: number) => {
    setCurrentChapterIndex(idx);
    if (window.innerWidth < 768) {
      setIsSidebarOpen(false);
    }
  };

  // --- PDF Preview Mode ---
  if (isPreviewOpen) {
    return (
      <div className="fixed inset-0 z-[100] bg-white overflow-y-auto">
        <style>
          {`
            @media print {
              /* 1. Reset Global Layout Constraints */
              html, body, #root {
                height: auto !important;
                width: 100% !important;
                overflow: visible !important;
                position: static !important;
                margin: 0 !important;
                padding: 0 !important;
              }

              /* 2. Hide everything by default using visibility */
              body {
                visibility: hidden;
              }

              /* 3. Target our specific print content wrapper */
              #print-content {
                visibility: visible !important;
                position: absolute !important;
                left: 0 !important;
                top: 0 !important;
                width: 100% !important;
                margin: 0 !important;
                padding: 0 !important;
                background: white;
                display: block !important;
              }

              /* 4. Ensure children are visible */
              #print-content * {
                visibility: visible !important;
              }

              /* 5. Hide UI elements explicitly marked */
              .no-print {
                display: none !important;
              }

              /* 6. Page setup */
              @page {
                margin: 20mm;
                size: auto;
              }

              /* 7. Typography fixes for print */
              .prose {
                max-width: none !important;
                color: black !important;
                font-size: 12pt !important;
                line-height: 1.5 !important;
              }

              h1, h2, h3 {
                page-break-after: avoid;
                color: black !important;
              }

              img {
                max-width: 100% !important;
              }

              .page-break {
                page-break-before: always;
                min-height: 1px; /* Ensure break is respected */
              }
            }
          `}
        </style>

        {/* Print Toolbar */}
        <div className="sticky top-0 z-50 bg-slate-900 text-white p-4 flex justify-between items-center shadow-lg no-print">
           <div className="flex items-center gap-4">
              <button onClick={() => setIsPreviewOpen(false)} className="flex items-center gap-2 text-sm font-bold text-slate-300 hover:text-white">
                 <ChevronLeft size={16} /> Back to Editor
              </button>
              <div className="h-4 w-px bg-slate-700"></div>
              <span className="font-serif font-bold">{outline.title} (Preview)</span>
           </div>
           <button 
             onClick={handlePrint}
             className="bg-blue-600 hover:bg-blue-500 text-white px-6 py-2 rounded-md font-bold text-sm flex items-center gap-2 shadow-sm"
           >
             <Printer size={16} /> Print / Save as PDF
           </button>
        </div>

        {/* Book Content (Print Layout) */}
        <div id="print-content" className="max-w-[800px] mx-auto bg-white p-12 md:p-24 min-h-screen shadow-2xl md:my-12 print:shadow-none print:p-0 print:m-0 print:w-full print:max-w-none">

           {/* Title Page */}
           <div className="flex flex-col items-center justify-center min-h-[800px] text-center page-break mb-24">
              <h1 className="text-5xl md:text-6xl font-serif font-bold text-slate-900 mb-6 leading-tight">{outline.title}</h1>
              <div className="w-16 h-1 bg-slate-900 mb-8"></div>
              <p className="text-sm uppercase tracking-[0.3em] text-slate-500 mb-12">A Lore Original</p>

              {outline.coverImage && (
                <img src={`data:image/jpeg;base64,${outline.coverImage}`} className="w-64 h-64 object-cover shadow-lg mb-12 print:shadow-none border border-slate-100" />
              )}

              <p className="max-w-md text-slate-600 italic font-serif leading-relaxed">{outline.description}</p>
           </div>

           {/* Chapters */}
           {chapters.map((chapter) => (
             <div key={chapter.chapterNumber} className="page-break mt-12">
                <div className="text-center mb-12 mt-8">
                   <span className="text-xs font-bold uppercase tracking-widest border-b border-slate-300 pb-2 mb-4 inline-block">Chapter {chapter.chapterNumber}</span>
                   <h2 className="text-3xl font-serif font-bold text-slate-900">{chapter.title}</h2>
                </div>

                <div className="prose prose-lg prose-slate font-serif max-w-none text-justify leading-loose">
                   <ReactMarkdown>{chapter.content}</ReactMarkdown>
                </div>
             </div>
           ))}

           <div className="text-center mt-24 pt-12 border-t border-slate-100 text-xs text-slate-400">
              Generated with Lore
           </div>
        </div>
      </div>
    );
  }

  // --- Normal Editor Mode ---
  return (
    <>
      {notification && (
        <Notification message={notification.message} type={notification.type} onClose={() => setNotification(null)} />
      )}

      <div className="flex flex-col md:flex-row h-[calc(100vh-4rem)] bg-slate-50 relative overflow-hidden">

        {/* Sidebar */}
        <div className={`
            flex-col bg-white border-r border-slate-200 flex-shrink-0 transition-all duration-300 z-30
            ${isSidebarOpen ? 'fixed inset-0 w-full flex md:static md:w-80' : 'hidden md:flex md:w-0 md:overflow-hidden'}
        `}>
          <div className="p-6 border-b border-slate-100 flex-shrink-0 flex justify-between items-start">
             <div className="overflow-hidden">
               <h3 className="font-bold text-slate-900 font-serif mb-1 truncate">{outline.title}</h3>
               <p className="text-xs text-slate-500 uppercase tracking-wider font-semibold">Table of Contents</p>
             </div>
             <button onClick={() => setIsSidebarOpen(false)} className="md:hidden p-1 text-slate-400 hover:text-slate-600">
               <X size={24} />
             </button>
          </div>

          {/* Unified Scrollable Area: Holds both chapters and controls */}
          <div className="flex-1 overflow-y-auto">
             <div className="p-4 space-y-2">
               {chapters.map((chap, idx) => (
                 <button
                   key={chap.chapterNumber}
                   onClick={() => handleChapterSelect(idx)}
                   className={`w-full text-left p-3 rounded-lg text-sm transition-all border ${
                     currentChapterIndex === idx 
