  onUpdateOutline?: (outline: BookOutline) => void;
}

const DEFAULT_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbxntoxi2DILyS_K3zQlZx9DSUDMupWW9x_p4sfWkCsKzB1Yv38SVSaylfVIX_bAOp4_/exec";

// Audio Cache to prevent re-fetching
const audioCache = new Map<string, AudioBuffer>();

// Helpers for Gemini Audio (PCM)
function decode(base64: string) {
  try {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  } catch (e) {
    console.error("Audio decoding failed", e);
    return new Uint8Array(0);
  }
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number = 24000,
  numChannels: number = 1
): Promise<AudioBuffer> {
  // CRITICAL IOS FIX: Int16Array requires 2-byte alignment.
  // If the byte length is odd, we must slice it to make it even.
  let bufferToUse = data.buffer;
  let byteOffset = data.byteOffset;
  let byteLength = data.byteLength;

  if (byteLength % 2 !== 0) {
      const newBuffer = new Uint8Array(byteLength - 1);
      newBuffer.set(data.subarray(0, byteLength - 1));
      bufferToUse = newBuffer.buffer;
      byteOffset = 0;
      byteLength = newBuffer.byteLength;
  }

  const dataInt16 = new Int16Array(bufferToUse, byteOffset, byteLength / 2);
  const frameCount = dataInt16.length / numChannels;

  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

export const BookReader: React.FC<BookReaderProps> = ({ 
  outline, 
  chapters, 
  onChapterUpdate, 
  selectedVoice, 
  onVoiceChange,
  onUpdateOutline
}) => {
  const [currentChapterIndex, setCurrentChapterIndex] = useState(0);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isPlaying, setIsPlaying] = useState(false);
  const [audioLoading, setAudioLoading] = useState(false);
  const [isExportingDocs, setIsExportingDocs] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editContent, setEditContent] = useState('');
  const [polishInstruction, setPolishInstruction] = useState('');
  const [isPolishing, setIsPolishing] = useState(false);
  const [isCoverGenerating, setIsCoverGenerating] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'error' | 'success'} | null>(null);

  // PDF Preview State
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);

  const audioContextRef = useRef<AudioContext | null>(null);
  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  const currentChapter = chapters[currentChapterIndex];

  useEffect(() => {
    stopAudio();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentChapterIndex]);

  const showNotification = (message: string, type: 'error' | 'success' = 'success') => {
    setNotification({ message, type });
    setTimeout(() => setNotification(null), 4000);
  };

  const stopAudio = () => {
    if (audioSourceRef.current) {
      try { audioSourceRef.current.stop(); } catch(e) {}
      audioSourceRef.current = null;
    }
    setIsPlaying(false);
  };

  const playChapterAudio = async () => {
    if (isPlaying) {
      stopAudio();
      return;
    }

    if (!currentChapter?.content) return;

    let silentSource: AudioBufferSourceNode | null = null;
    let ctx = audioContextRef.current;

    // --- iOS Audio Unlock Sequence ---
    try {
      if (!ctx) {
        // Handle standard and WebKit prefix for Safari
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
        ctx = new AudioContextClass();
        audioContextRef.current = ctx;
      }

      // Resume context immediately within the click handler
      if (ctx.state === 'suspended') {
        await ctx.resume();
      }

      // Play a short silent buffer to force the audio engine to wake up on iOS
      const silentBuffer = ctx.createBuffer(1, 1, 22050); 
      silentSource = ctx.createBufferSource();
      silentSource.buffer = silentBuffer;
      silentSource.connect(ctx.destination);
      silentSource.start();

    } catch (e) {
      console.error("Audio unlock failed", e);
      showNotification("Could not access audio hardware.", 'error');
      return;
    }

    const cacheKey = `${currentChapter.chapterNumber}-${selectedVoice}-${currentChapter.content.length}`;
    if (audioCache.has(cacheKey)) {
        if (silentSource) {
            try { (silentSource as AudioBufferSourceNode).stop(); } catch(e) {}
        }
        playBuffer(audioCache.get(cacheKey)!);
        return;
    }

    setAudioLoading(true);

    try {
      const pcmBase64 = await generateSpeech(currentChapter.content.slice(0, 5000), selectedVoice || 'Kore');

      // Re-check context existence
      if (!audioContextRef.current) {
          const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
          audioContextRef.current = new AudioContextClass();
      }
      ctx = audioContextRef.current!;

      const pcmData = decode(pcmBase64);
      const audioBuffer = await decodeAudioData(pcmData, ctx, 24000);

      audioCache.set(cacheKey, audioBuffer);

      if (silentSource) {
         try { (silentSource as AudioBufferSourceNode).stop(); } catch(e) {}
      }

      playBuffer(audioBuffer);

    } catch (err: any) {
      console.error("Audio playback failed", err);
      if (silentSource) {
        try { (silentSource as AudioBufferSourceNode).stop(); } catch(e) {}
      }
      showNotification("Failed to generate audio. " + (err.message || ""), 'error');
    } finally {
      setAudioLoading(false);
    }
  };

  const playBuffer = (buffer: AudioBuffer) => {
    const ctx = audioContextRef.current;
    if (!ctx) return;

    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.connect(ctx.destination);
    source.onended = () => setIsPlaying(false);

    audioSourceRef.current = source;
    source.start();
    setIsPlaying(true);
  };

  const handlePrint = () => {
    window.print();
  };

  const handleExportDocs = async () => {
    setIsExportingDocs(true);

    const scriptUrl = prompt("Enter Google Apps Script URL:", DEFAULT_SCRIPT_URL);
    if (!scriptUrl) {
      setIsExportingDocs(false);
      return;
    }

    try {
      await fetch(scriptUrl, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title: outline.title,
          description: outline.description,
          chapters: chapters.map(c => ({
            chapterNumber: c.chapterNumber,
            title: c.title,
            content: c.content
          }))
        })
      });
      showNotification("Export request sent to Google Docs!");
    } catch (e) {
      console.error(e);
      showNotification("Docs export failed.", 'error');
    } finally {
      setIsExportingDocs(false);
    }
  };

  const startEditing = () => {
    if (!currentChapter) return;
    setEditContent(currentChapter.content);
    setIsEditing(true);
  };

  const saveEditing = () => {
    if (!currentChapter || !onChapterUpdate) return;
    onChapterUpdate({
      ...currentChapter,
      content: editContent
    });
    setIsEditing(false);
    showNotification("Changes saved.");
  };

  const cancelEditing = () => {
    setIsEditing(false);
    setPolishInstruction('');
  };

  const handlePolish = async () => {
    if (!polishInstruction.trim()) return;
    setIsPolishing(true);
    try {
      const polished = await refineChapterText(editContent, polishInstruction);
      setEditContent(polished);
      setPolishInstruction('');
      showNotification("Text refined!");
    } catch (e) {
      console.error(e);
      showNotification("Polish failed.", 'error');
    } finally {
      setIsPolishing(false);
    }
  };

  const handleGenerateCover = async () => {
    if (!onUpdateOutline) return;
    setIsCoverGenerating(true);
    try {
      const prompt = `A professional, high-quality book cover for a book titled "${outline.title}". 
      Description: ${outline.description}. 
      Style: Minimalist, modern, striking typography, best-selling aesthetic.`;

      const base64Image = await generateImage(prompt, '1:1');
      onUpdateOutline({
        ...outline,
        coverImage: base64Image
      });
      showNotification("Cover updated!");
    } catch (e) {
      console.error(e);
      showNotification("Failed to generate cover.", 'error');
    } finally {
      setIsCoverGenerating(false);
    }
  };

  const handleChapterSelect = (idx: number) => {
    setCurrentChapterIndex(idx);
    if (window.innerWidth < 768) {
      setIsSidebarOpen(false);
    }
  };

  // --- PDF Preview Mode ---
  if (isPreviewOpen) {
    return (
      <div className="fixed inset-0 z-[100] bg-white overflow-y-auto">
        <style>
          {`
            @media print {
              /* 1. Reset Global Layout Constraints */
              html, body, #root {
                height: auto !important;
                width: 100% !important;
                overflow: visible !important;
                position: static !important;
                margin: 0 !important;
                padding: 0 !important;
              }

              /* 2. Hide everything by default using visibility */
              body {
                visibility: hidden;
              }

              /* 3. Target our specific print content wrapper */
              #print-content {
                visibility: visible !important;
                position: absolute !important;
                left: 0 !important;
                top: 0 !important;
                width: 100% !important;
                margin: 0 !important;
                padding: 0 !important;
                background: white;
                display: block !important;
              }

              /* 4. Ensure children are visible */
              #print-content * {
                visibility: visible !important;
              }

              /* 5. Hide UI elements explicitly marked */
              .no-print {
                display: none !important;
              }

              /* 6. Page setup */
              @page {
                margin: 20mm;
                size: auto;
              }

              /* 7. Typography fixes for print */
              .prose {
                max-width: none !important;
                color: black !important;
                font-size: 12pt !important;
                line-height: 1.5 !important;
              }

              h1, h2, h3 {
                page-break-after: avoid;
                color: black !important;
              }

              img {
                max-width: 100% !important;
              }

              .page-break {
                page-break-before: always;
                min-height: 1px; /* Ensure break is respected */
              }
            }
          `}
        </style>

        {/* Print Toolbar */}
        <div className="sticky top-0 z-50 bg-slate-900 text-white p-4 flex justify-between items-center shadow-lg no-print">
           <div className="flex items-center gap-4">
              <button onClick={() => setIsPreviewOpen(false)} className="flex items-center gap-2 text-sm font-bold text-slate-300 hover:text-white">
                 <ChevronLeft size={16} /> Back to Editor
              </button>
              <div className="h-4 w-px bg-slate-700"></div>
              <span className="font-serif font-bold">{outline.title} (Preview)</span>
           </div>
           <button 
             onClick={handlePrint}
             className="bg-blue-600 hover:bg-blue-500 text-white px-6 py-2 rounded-md font-bold text-sm flex items-center gap-2 shadow-sm"
           >
             <Printer size={16} /> Print / Save as PDF
           </button>
        </div>

        {/* Book Content (Print Layout) */}
        <div id="print-content" className="max-w-[800px] mx-auto bg-white p-12 md:p-24 min-h-screen shadow-2xl md:my-12 print:shadow-none print:p-0 print:m-0 print:w-full print:max-w-none">

           {/* Title Page */}
           <div className="flex flex-col items-center justify-center min-h-[800px] text-center page-break mb-24">
              <h1 className="text-5xl md:text-6xl font-serif font-bold text-slate-900 mb-6 leading-tight">{outline.title}</h1>
              <div className="w-16 h-1 bg-slate-900 mb-8"></div>
              <p className="text-sm uppercase tracking-[0.3em] text-slate-500 mb-12">A Lore Original</p>

              {outline.coverImage && (
                <img src={`data:image/jpeg;base64,${outline.coverImage}`} className="w-64 h-64 object-cover shadow-lg mb-12 print:shadow-none border border-slate-100" />
              )}

              <p className="max-w-md text-slate-600 italic font-serif leading-relaxed">{outline.description}</p>
           </div>

           {/* Chapters */}
           {chapters.map((chapter) => (
             <div key={chapter.chapterNumber} className="page-break mt-12">
                <div className="text-center mb-12 mt-8">
                   <span className="text-xs font-bold uppercase tracking-widest border-b border-slate-300 pb-2 mb-4 inline-block">Chapter {chapter.chapterNumber}</span>
                   <h2 className="text-3xl font-serif font-bold text-slate-900">{chapter.title}</h2>
                </div>

                <div className="prose prose-lg prose-slate font-serif max-w-none text-justify leading-loose">
                   <ReactMarkdown>{chapter.content}</ReactMarkdown>
                </div>
             </div>
           ))}

           <div className="text-center mt-24 pt-12 border-t border-slate-100 text-xs text-slate-400">
              Generated with Lore
           </div>
        </div>
      </div>
    );
  }

  // --- Normal Editor Mode ---
  return (
    <>
      {notification && (
        <Notification message={notification.message} type={notification.type} onClose={() => setNotification(null)} />
      )}

      <div className="flex flex-col md:flex-row h-[calc(100vh-4rem)] bg-slate-50 relative overflow-hidden">

        {/* Sidebar */}
        <div className={`
            flex-col bg-white border-r border-slate-200 flex-shrink-0 transition-all duration-300 z-30
            ${isSidebarOpen ? 'fixed inset-0 w-full flex md:static md:w-80' : 'hidden md:flex md:w-0 md:overflow-hidden'}
        `}>
          <div className="p-6 border-b border-slate-100 flex-shrink-0 flex justify-between items-start">
             <div className="overflow-hidden">
               <h3 className="font-bold text-slate-900 font-serif mb-1 truncate">{outline.title}</h3>
               <p className="text-xs text-slate-500 uppercase tracking-wider font-semibold">Table of Contents</p>
             </div>
             <button onClick={() => setIsSidebarOpen(false)} className="md:hidden p-1 text-slate-400 hover:text-slate-600">
               <X size={24} />
             </button>
          </div>

          {/* Unified Scrollable Area: Holds both chapters and controls */}
          <div className="flex-1 overflow-y-auto">
             <div className="p-4 space-y-2">
               {chapters.map((chap, idx) => (
                 <button
                   key={chap.chapterNumber}
                   onClick={() => handleChapterSelect(idx)}
                   className={`w-full text-left p-3 rounded-lg text-sm transition-all border ${
                     currentChapterIndex === idx 
                     ? 'bg-blue-50 border-blue-200 text-blue-800 font-bold shadow-sm' 
                     : 'border-transparent hover:bg-slate-50 text-slate-600'
                   }`}
                 >
                   <div className="flex justify-between items-center mb-1">
                      <span className="text-xs opacity-70 uppercase tracking-wide">Chapter {chap.chapterNumber}</span>
                      {chap.isGenerating && <Loader2 size={12} className="animate-spin text-blue-500"/>}
                   </div>
                   <div className="truncate">{chap.title}</div>
                 </button>
               ))}
             </div>

             <div className="p-4 border-t border-slate-100 bg-slate-50/50 space-y-3">
                <div className="bg-white p-3 rounded-lg border border-slate-200 shadow-sm">
                   <div className="flex items-center gap-2 mb-2 text-xs font-bold text-slate-400 uppercase tracking-wider">
                     <Headphones size={12} /> Audiobook
                   </div>
                   <select 
                      value={selectedVoice}
                      onChange={(e) => onVoiceChange && onVoiceChange(e.target.value)}
                      className="w-full text-sm p-2 bg-slate-50 border border-slate-200 rounded mb-2 outline-none focus:border-blue-300"
                   >
                     <option value="Kore">Kore (Balanced)</option>
                     <option value="Puck">Puck (Energetic)</option>
                     <option value="Fenrir">Fenrir (Deep)</option>
                     <option value="Charon">Charon (Calm)</option>
                   </select>
                   <button 
                     onClick={playChapterAudio}
                     disabled={audioLoading || !currentChapter || currentChapter.isGenerating}
                     className={`w-full py-2 rounded-md font-bold text-sm text-white flex items-center justify-center gap-2 transition-all ${isPlaying ? 'bg-slate-800 hover:bg-slate-900' : 'bg-blue-600 hover:bg-blue-500 shadow-sm'}`}
                   >
                     {audioLoading ? <Loader2 size={14} className="animate-spin" /> : isPlaying ? <Square size={14} fill="currentColor" /> : <Play size={14} fill="currentColor" />}
                     {isPlaying ? 'Stop Reading' : 'Read Chapter'}
                   </button>
                </div>

                <div className="bg-white p-4 rounded-lg border border-slate-200 shadow-sm">
                   <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3">Design & Export</div>

                   <div className="mb-4">
                     {outline.coverImage ? (
                       <div className="relative group rounded-md overflow-hidden mb-2 border border-slate-100 shadow-sm">
                          <img src={`data:image/jpeg;base64,${outline.coverImage}`} alt="Cover" className="w-full h-full object-cover aspect-square" />
                          <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                             <button onClick={handleGenerateCover} className="text-white text-xs font-bold flex items-center gap-1 hover:underline">
                                <ImageIcon size={12} /> Regenerate
                             </button>
                          </div>
                       </div>
                     ) : (
                       <button 
                         onClick={handleGenerateCover}
                         disabled={isCoverGenerating}
                         className="w-full py-2 px-3 bg-purple-50 hover:bg-purple-100 text-purple-700 rounded-md text-xs font-bold flex items-center justify-center gap-2 transition-all mb-2"
                       >
                         {isCoverGenerating ? <Loader2 size={12} className="animate-spin" /> : <Sparkles size={12} />}
                         Generate Full Cover
                       </button>
                     )}
                   </div>

                   <button 
                     onClick={() => setIsPreviewOpen(true)}
                     className="w-full flex items-center gap-2 text-slate-600 hover:text-blue-700 hover:bg-slate-50 p-2 rounded-md text-sm font-medium transition-colors mb-1"
                   >
                     <Download size={16} />
                     Download E-Book (PDF)
                   </button>
                   <button 
                     onClick={handleExportDocs}
                     disabled={isExportingDocs}
                     className="w-full flex items-center gap-2 text-slate-600 hover:text-blue-700 hover:bg-slate-50 p-2 rounded-md text-sm font-medium transition-colors"
                   >
                     {isExportingDocs ? <Loader2 size={16} className="animate-spin" /> : <FileText size={16} />}
                     Export to Docs
                   </button>
                </div>
             </div>
          </div>

        </div>

        {/* Reader Content */}
        <div className="flex-1 flex flex-col h-full overflow-hidden bg-slate-50 relative w-full">

           <div className="md:hidden h-14 bg-white border-b border-slate-200 flex items-center px-4 shrink-0 justify-between">
              <button onClick={() => setIsSidebarOpen(true)} className="p-2 -ml-2 text-slate-600 hover:bg-slate-100 rounded-lg">
                 <Menu size={24} />
              </button>
              <span className="font-serif font-bold text-slate-900 truncate max-w-[200px]">
                 {currentChapter ? `Ch ${currentChapter.chapterNumber}: ${currentChapter.title}` : 'Reader'}
              </span>
              <div className="w-8"></div>
           </div>

           <div className="hidden md:block absolute top-4 left-4 z-20">
              <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 bg-white shadow-md rounded-lg border border-slate-200 text-slate-600 hover:text-blue-600 transition-colors">
                 {isSidebarOpen ? <ChevronLeft size={20} /> : <ChevronRight size={20} />}
              </button>
           </div>

           <div className="flex-1 overflow-y-auto p-4 md:p-12 scroll-smooth">
             <div className="max-w-3xl mx-auto bg-white shadow-xl shadow-slate-200/50 min-h-[80vh] p-6 md:p-16 rounded-xl relative border border-slate-100">

                <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-blue-100 via-blue-50 to-blue-100 opacity-50"></div>

                {!currentChapter ? (
                  <div className="flex flex-col items-center justify-center h-64 text-slate-400">
                    <Loader2 size={40} className="animate-spin mb-4 text-blue-200" />
                    <p>Loading Manuscript...</p>
                  </div>
                ) : (
                  <>
                    <div className="mb-8 pb-8 border-b border-slate-100">
                       <span className="text-xs font-bold tracking-[0.2em] text-slate-400 uppercase mb-2 block text-center">Chapter {currentChapter.chapterNumber}</span>
                       <h2 className="text-2xl md:text-4xl font-serif font-bold text-slate-900 text-center leading-tight">{currentChapter.title}</h2>
                    </div>

                    {isEditing ? (
                       <div className="animate-in fade-in">
                          <textarea 
                             value={editContent}
                             onChange={(e) => setEditContent(e.target.value)}
                             className="w-full h-[60vh] p-4 font-serif text-lg leading-relaxed text-slate-800 border-2 border-blue-100 rounded-lg outline-none focus:ring-2 focus:ring-blue-200 resize-y mb-4"
                          />

                          <div className="bg-blue-50 p-4 rounded-xl border border-blue-100 mb-6 flex gap-3 items-center">
                             <div className="bg-blue-200 p-2 rounded-full text-blue-700"><Wand2 size={16} /></div>
                             <div className="flex-1">
                                <input 
                                  value={polishInstruction}
                                  onChange={(e) => setPolishInstruction(e.target.value)}
                                  placeholder="Ask AI to polish (e.g., 'Make it more dramatic')"
                                  className="w-full bg-white border border-blue-200 rounded px-3 py-2 text-sm outline-none focus:border-blue-400"
                                  onKeyDown={(e) => e.key === 'Enter' && handlePolish()}
                                />
                             </div>
                             <button 
                               onClick={handlePolish}
                               disabled={isPolishing || !polishInstruction.trim()}
                               className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white text-sm font-bold rounded-lg transition-colors disabled:opacity-50"
                             >
                               {isPolishing ? <Loader2 size={16} className="animate-spin" /> : 'Refine'}
                             </button>
                          </div>

                          <div className="flex justify-end gap-3 sticky bottom-0 bg-white pt-4 border-t border-slate-100">
                             <button onClick={cancelEditing} className="px-5 py-2.5 text-slate-600 font-bold text-sm hover:bg-slate-100 rounded-lg">Cancel</button>
                             <button onClick={saveEditing} className="px-5 py-2.5 bg-emerald-600 hover:bg-emerald-500 text-white font-bold text-sm rounded-lg shadow-lg shadow-emerald-200 flex items-center gap-2">
                                <Save size={16} /> Save Changes
                             </button>
                          </div>
                       </div>
                    ) : (
                      <div className="prose prose-lg prose-slate font-serif max-w-none prose-headings:font-sans prose-headings:font-bold prose-p:leading-loose text-slate-800">
                         {currentChapter.isGenerating ? (
                           <div className="space-y-4 animate-pulse">
                              <div className="h-4 bg-slate-100 rounded w-full"></div>
                              <div className="h-4 bg-slate-100 rounded w-11/12"></div>
                              <div className="h-4 bg-slate-100 rounded w-full"></div>
                              <div className="py-8 text-center text-slate-400 text-sm font-sans flex items-center justify-center gap-2">
                                <Loader2 size={16} className="animate-spin" /> Writing in progress...
                              </div>
                           </div>
                         ) : (
                           <div className="relative group min-h-[200px]">
                              <ReactMarkdown>{currentChapter.content}</ReactMarkdown>
                              <button 
                                onClick={startEditing}
                                className="absolute top-0 right-0 p-2 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-lg opacity-0 group-hover:opacity-100 transition-all"
                                title="Edit Text"
                              >
                                <PenLine size={20} />
                              </button>
                           </div>
                         )}
                      </div>
                    )}
                  </>
                )}
             </div>

             <div className="max-w-3xl mx-auto mt-8 flex justify-between items-center text-sm font-medium text-slate-500 pb-24 md:pb-12 px-4">
                <button 
                  onClick={() => setCurrentChapterIndex(prev => Math.max(0, prev - 1))}
                  disabled={currentChapterIndex === 0}
                  className="flex items-center gap-2 hover:text-blue-600 disabled:opacity-30 disabled:hover:text-slate-500 transition-colors px-4 py-2 hover:bg-white rounded-full"
                >
                  <ChevronLeft size={16} /> Previous
                </button>
                <span>{currentChapterIndex + 1} / {chapters.length}</span>
                <button 
                  onClick={() => setCurrentChapterIndex(prev => Math.min(chapters.length - 1, prev + 1))}
                  disabled={currentChapterIndex === chapters.length - 1}
                  className="flex items-center gap-2 hover:text-blue-600 disabled:opacity-30 disabled:hover:text-slate-500 transition-colors px-4 py-2 hover:bg-white rounded-full"
                >
                  Next <ChevronRight size={16} />
                </button>
             </div>
           </div>
        </div>
      </div>
    </>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { ChapterContent, BookOutline } from '../types';
import { ChevronLeft, ChevronRight, Loader2, Download, PenLine, Save, Headphones, Play, Square, FileText, Image as ImageIcon, Wand2, Menu, X, Sparkles, Printer } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import { generateSpeech, generateImage, refineChapterText } from '../services/gemini';
import { Notification } from './Notification';

interface BookReaderProps {
  outline: BookOutline;
  chapters: ChapterContent[];
  onChapterUpdate?: (chapter: ChapterContent) => void;
  selectedVoice?: string;
  onVoiceChange?: (voice: string) => void;
  onUpdateOutline?: (outline: BookOutline) => void;
}

const DEFAULT_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbxntoxi2DILyS_K3zQlZx9DSUDMupWW9x_p4sfWkCsKzB1Yv38SVSaylfVIX_bAOp4_/exec";

// Audio Cache to prevent re-fetching
const audioCache = new Map<string, AudioBuffer>();

// Helpers for Gemini Audio (PCM)
function decode(base64: string) {
  try {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  } catch (e) {
    console.error("Audio decoding failed", e);
    return new Uint8Array(0);
  }
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number = 24000,
  numChannels: number = 1
): Promise<AudioBuffer> {
  // CRITICAL IOS FIX: Int16Array requires 2-byte alignment.
  // If the byte length is odd, we must slice it to make it even.
  let bufferToUse = data.buffer;
  let byteOffset = data.byteOffset;
  let byteLength = data.byteLength;

  if (byteLength % 2 !== 0) {
      const newBuffer = new Uint8Array(byteLength - 1);
      newBuffer.set(data.subarray(0, byteLength - 1));
      bufferToUse = newBuffer.buffer;
      byteOffset = 0;
      byteLength = newBuffer.byteLength;
  }

  const dataInt16 = new Int16Array(bufferToUse, byteOffset, byteLength / 2);
  const frameCount = dataInt16.length / numChannels;

  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

export const BookReader: React.FC<BookReaderProps> = ({ 
  outline, 
  chapters, 
  onChapterUpdate, 
  selectedVoice, 
  onVoiceChange,
  onUpdateOutline
}) => {
  const [currentChapterIndex, setCurrentChapterIndex] = useState(0);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isPlaying, setIsPlaying] = useState(false);
  const [audioLoading, setAudioLoading] = useState(false);
  const [isExportingDocs, setIsExportingDocs] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editContent, setEditContent] = useState('');
  const [polishInstruction, setPolishInstruction] = useState('');
  const [isPolishing, setIsPolishing] = useState(false);
  const [isCoverGenerating, setIsCoverGenerating] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'error' | 'success'} | null>(null);

  // PDF Preview State
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);
  const [isPrinting, setIsPrinting] = useState(false);

  const audioContextRef = useRef<AudioContext | null>(null);
  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  const currentChapter = chapters[currentChapterIndex];

  useEffect(() => {
    stopAudio();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentChapterIndex]);

  const showNotification = (message: string, type: 'error' | 'success' = 'success') => {
    setNotification({ message, type });
    setTimeout(() => setNotification(null), 4000);
  };

  const stopAudio = () => {
    if (audioSourceRef.current) {
      try { audioSourceRef.current.stop(); } catch(e) {}
      audioSourceRef.current = null;
    }
    setIsPlaying(false);
  };

  const playChapterAudio = async () => {
    if (isPlaying) {
      stopAudio();
      return;
    }

    if (!currentChapter?.content) return;

    let silentSource: AudioBufferSourceNode | null = null;
    let ctx = audioContextRef.current;

    // --- iOS Audio Unlock Sequence ---
    try {
      if (!ctx) {
        // Handle standard and WebKit prefix for Safari
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
        ctx = new AudioContextClass();
        audioContextRef.current = ctx;
      }

      // Resume context immediately within the click handler
      if (ctx.state === 'suspended') {
        await ctx.resume();
      }

      // Play a short silent buffer to force the audio engine to wake up on iOS
      const silentBuffer = ctx.createBuffer(1, 1, 22050); 
      silentSource = ctx.createBufferSource();
      silentSource.buffer = silentBuffer;
      silentSource.connect(ctx.destination);
      silentSource.start();

    } catch (e) {
      console.error("Audio unlock failed", e);
      showNotification("Could not access audio hardware.", 'error');
      return;
    }

    const cacheKey = `${currentChapter.chapterNumber}-${selectedVoice}-${currentChapter.content.length}`;
    if (audioCache.has(cacheKey)) {
        if (silentSource) {
            try { (silentSource as AudioBufferSourceNode).stop(); } catch(e) {}
        }
        playBuffer(audioCache.get(cacheKey)!);
        return;
    }

    setAudioLoading(true);

    try {
      const pcmBase64 = await generateSpeech(currentChapter.content.slice(0, 5000), selectedVoice || 'Kore');

      // Re-check context existence
      if (!audioContextRef.current) {
          const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
          audioContextRef.current = new AudioContextClass();
      }
      ctx = audioContextRef.current!;

      const pcmData = decode(pcmBase64);
      const audioBuffer = await decodeAudioData(pcmData, ctx, 24000);

      audioCache.set(cacheKey, audioBuffer);

      if (silentSource) {
         try { (silentSource as AudioBufferSourceNode).stop(); } catch(e) {}
      }

      playBuffer(audioBuffer);

    } catch (err: any) {
      console.error("Audio playback failed", err);
      if (silentSource) {
        try { (silentSource as AudioBufferSourceNode).stop(); } catch(e) {}
      }
      showNotification("Failed to generate audio. " + (err.message || ""), 'error');
    } finally {
      setAudioLoading(false);
    }
  };

  const playBuffer = (buffer: AudioBuffer) => {
    const ctx = audioContextRef.current;
    if (!ctx) return;

    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.connect(ctx.destination);
    source.onended = () => setIsPlaying(false);

    audioSourceRef.current = source;
    source.start();
    setIsPlaying(true);
  };

  const handlePrint = () => {
    setIsPrinting(true);
    // Use a small timeout to allow UI to render 'Preparing' state
    // and ensure browser is ready to capture the specific print view
    setTimeout(() => {
      window.print();
      setIsPrinting(false);
    }, 100);
  };

  const handleExportDocs = async () => {
    setIsExportingDocs(true);

    const scriptUrl = prompt("Enter Google Apps Script URL:", DEFAULT_SCRIPT_URL);
    if (!scriptUrl) {
      setIsExportingDocs(false);
      return;
    }

    try {
      await fetch(scriptUrl, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title: outline.title,
          description: outline.description,
          chapters: chapters.map(c => ({
            chapterNumber: c.chapterNumber,
            title: c.title,
            content: c.content
          }))
        })
      });
      showNotification("Export request sent to Google Docs!");
    } catch (e) {
      console.error(e);
      showNotification("Docs export failed.", 'error');
    } finally {
      setIsExportingDocs(false);
    }
  };

  const startEditing = () => {
    if (!currentChapter) return;
    setEditContent(currentChapter.content);
    setIsEditing(true);
  };

  const saveEditing = () => {
    if (!currentChapter || !onChapterUpdate) return;
    onChapterUpdate({
      ...currentChapter,
      content: editContent
    });
    setIsEditing(false);
    showNotification("Changes saved.");
  };

  const cancelEditing = () => {
    setIsEditing(false);
    setPolishInstruction('');
  };

  const handlePolish = async () => {
    if (!polishInstruction.trim()) return;
    setIsPolishing(true);
    try {
      const polished = await refineChapterText(editContent, polishInstruction);
      setEditContent(polished);
      setPolishInstruction('');
      showNotification("Text refined!");
    } catch (e) {
      console.error(e);
      showNotification("Polish failed.", 'error');
    } finally {
      setIsPolishing(false);
    }
  };

  const handleGenerateCover = async () => {
    if (!onUpdateOutline) return;
    setIsCoverGenerating(true);
    try {
      const prompt = `A professional, high-quality book cover for a book titled "${outline.title}". 
      Description: ${outline.description}. 
      Style: Minimalist, modern, striking typography, best-selling aesthetic.`;

      const base64Image = await generateImage(prompt, '1:1');
      onUpdateOutline({
        ...outline,
        coverImage: base64Image
      });
      showNotification("Cover updated!");
    } catch (e) {
      console.error(e);
      showNotification("Failed to generate cover.", 'error');
    } finally {
      setIsCoverGenerating(false);
    }
  };

  const handleChapterSelect = (idx: number) => {
    setCurrentChapterIndex(idx);
    if (window.innerWidth < 768) {
      setIsSidebarOpen(false);
    }
  };

  return (
    <>
      {notification && (
        <Notification message={notification.message} type={notification.type} onClose={() => setNotification(null)} />
      )}

      {/* --- PDF Preview Overlay --- */}
      {isPreviewOpen && (
        <div className="fixed inset-0 z-[100] bg-white overflow-y-auto animate-in fade-in duration-200">
          <style>
            {`
              @media print {
                /* 1. Reset Global Layout Constraints */
                html, body, #root {
                  height: auto !important;
                  width: 100% !important;
                  overflow: visible !important;
                  position: static !important;
                  margin: 0 !important;
                  padding: 0 !important;
                }

                /* 2. Hide everything by default using visibility */
                body {
                  visibility: hidden;
                }

                /* 3. Target our specific print content wrapper */
                #print-content {
                  visibility: visible !important;
                  position: absolute !important;
                  left: 0 !important;
                  top: 0 !important;
                  width: 100% !important;
                  margin: 0 !important;
                  padding: 0 !important;
                  background: white;
                  display: block !important;
                }

                /* 4. Ensure children are visible */
                #print-content * {
                  visibility: visible !important;
                }

                /* 5. Hide UI elements explicitly marked */
                .no-print {
                  display: none !important;
                }

                /* 6. Page setup */
                @page {
                  margin: 20mm;
                  size: auto;
                }

                /* 7. Typography fixes for print */
                .prose {
                  max-width: none !important;
                  color: black !important;
                  font-size: 12pt !important;
                  line-height: 1.5 !important;
                }

                h1, h2, h3 {
                  page-break-after: avoid;
                  color: black !important;
                }

                img {
                  max-width: 100% !important;
                }

                .page-break {
                  page-break-before: always;
                  min-height: 1px; /* Ensure break is respected */
                }
              }
            `}
          </style>

          {/* Print Toolbar */}
          <div className="sticky top-0 z-50 bg-slate-900 text-white p-4 flex justify-between items-center shadow-lg no-print">
            <div className="flex items-center gap-4">
                <button 
                  onClick={() => !isPrinting && setIsPreviewOpen(false)} 
                  disabled={isPrinting}
                  className="flex items-center gap-2 text-sm font-bold text-slate-300 hover:text-white disabled:opacity-50 transition-colors"
                >
                  <ChevronLeft size={16} /> Back to Editor
                </button>
                <div className="h-4 w-px bg-slate-700"></div>
                <span className="font-serif font-bold">{outline.title} (Preview)</span>
            </div>
            <button 
              onClick={handlePrint}
              disabled={isPrinting}
              className={`bg-blue-600 hover:bg-blue-500 text-white px-6 py-2 rounded-md font-bold text-sm flex items-center gap-2 shadow-sm transition-all ${isPrinting ? 'opacity-80 cursor-wait' : ''}`}
            >
              {isPrinting ? <Loader2 size={16} className="animate-spin" /> : <Printer size={16} />}
              {isPrinting ? 'Preparing PDF...' : 'Print / Save as PDF'}
            </button>
          </div>

          {/* Book Content (Print Layout) */}
          <div id="print-content" className="max-w-[800px] mx-auto bg-white p-12 md:p-24 min-h-screen shadow-2xl md:my-12 print:shadow-none print:p-0 print:m-0 print:w-full print:max-w-none">

            {/* Title Page */}
            <div className="flex flex-col items-center justify-center min-h-[800px] text-center page-break mb-24">
                <h1 className="text-5xl md:text-6xl font-serif font-bold text-slate-900 mb-6 leading-tight">{outline.title}</h1>
                <div className="w-16 h-1 bg-slate-900 mb-8"></div>
                <p className="text-sm uppercase tracking-[0.3em] text-slate-500 mb-12">A Lore Original</p>

                {outline.coverImage && (
                  <img src={`data:image/jpeg;base64,${outline.coverImage}`} className="w-64 h-64 object-cover shadow-lg mb-12 print:shadow-none border border-slate-100" />
                )}

                <p className="max-w-md text-slate-600 italic font-serif leading-relaxed">{outline.description}</p>
            </div>

            {/* Chapters */}
            {chapters.map((chapter) => (
              <div key={chapter.chapterNumber} className="page-break mt-12">
                  <div className="text-center mb-12 mt-8">
                    <span className="text-xs font-bold uppercase tracking-widest border-b border-slate-300 pb-2 mb-4 inline-block">Chapter {chapter.chapterNumber}</span>
                    <h2 className="text-3xl font-serif font-bold text-slate-900">{chapter.title}</h2>
                  </div>

                  <div className="prose prose-lg prose-slate font-serif max-w-none text-justify leading-loose">
                    <ReactMarkdown>{chapter.content}</ReactMarkdown>
                  </div>
              </div>
            ))}

            <div className="text-center mt-24 pt-12 border-t border-slate-100 text-xs text-slate-400">
                Generated with Lore
            </div>
          </div>
        </div>
      )}

      {/* --- Main Editor (Hidden when previewing) --- */}
      <div className={`flex flex-col md:flex-row h-[calc(100vh-4rem)] bg-slate-50 relative overflow-hidden ${isPreviewOpen ? 'hidden' : ''}`}>

        {/* Sidebar */}
        <div className={`
            flex-col bg-white border-r border-slate-200 flex-shrink-0 transition-all duration-300 z-30
            ${isSidebarOpen ? 'fixed inset-0 w-full flex md:static md:w-80' : 'hidden md:flex md:w-0 md:overflow-hidden'}
        `}>
          <div className="p-6 border-b border-slate-100 flex-shrink-0 flex justify-between items-start">
             <div className="overflow-hidden">
               <h3 className="font-bold text-slate-900 font-serif mb-1 truncate">{outline.title}</h3>
               <p className="text-xs text-slate-500 uppercase tracking-wider font-semibold">Table of Contents</p>
             </div>
             <button onClick={() => setIsSidebarOpen(false)} className="md:hidden p-1 text-slate-400 hover:text-slate-600">
               <X size={24} />
             </button>
          </div>

          {/* Unified Scrollable Area: Holds both chapters and controls */}
          <div className="flex-1 overflow-y-auto">
             <div className="p-4 space-y-2">
               {chapters.map((chap, idx) => (
                 <button
                   key={chap.chapterNumber}
                   onClick={() => handleChapterSelect(idx)}
                   className={`w-full text-left p-3 rounded-lg text-sm transition-all border ${
                     currentChapterIndex === idx 
                     ? 'bg-blue-50 border-blue-200 text-blue-800 font-bold shadow-sm' 
                     : 'border-transparent hover:bg-slate-50 text-slate-600'
                   }`}
                 >
                   <div className="flex justify-between items-center mb-1">
                      <span className="text-xs opacity-70 uppercase tracking-wide">Chapter {chap.chapterNumber}</span>
                      {chap.isGenerating && <Loader2 size={12} className="animate-spin text-blue-500"/>}
                   </div>
                   <div className="truncate">{chap.title}</div>
                 </button>
               ))}
             </div>

             <div className="p-4 border-t border-slate-100 bg-slate-50/50 space-y-3">
                <div className="bg-white p-3 rounded-lg border border-slate-200 shadow-sm">
                   <div className="flex items-center gap-2 mb-2 text-xs font-bold text-slate-400 uppercase tracking-wider">
                     <Headphones size={12} /> Audiobook
                   </div>
                   <select 
                      value={selectedVoice}
                      onChange={(e) => onVoiceChange && onVoiceChange(e.target.value)}
                      className="w-full text-sm p-2 bg-slate-50 border border-slate-200 rounded mb-2 outline-none focus:border-blue-300"
                   >
                     <option value="Kore">Kore (Balanced)</option>
                     <option value="Puck">Puck (Energetic)</option>
                     <option value="Fenrir">Fenrir (Deep)</option>
                     <option value="Charon">Charon (Calm)</option>
                   </select>
                   <button 
                     onClick={playChapterAudio}
                     disabled={audioLoading || !currentChapter || currentChapter.isGenerating}
                     className={`w-full py-2 rounded-md font-bold text-sm text-white flex items-center justify-center gap-2 transition-all ${isPlaying ? 'bg-slate-800 hover:bg-slate-900' : 'bg-blue-600 hover:bg-blue-500 shadow-sm'}`}
                   >
                     {audioLoading ? <Loader2 size={14} className="animate-spin" /> : isPlaying ? <Square size={14} fill="currentColor" /> : <Play size={14} fill="currentColor" />}
                     {isPlaying ? 'Stop Reading' : 'Read Chapter'}
                   </button>
                </div>

                <div className="bg-white p-4 rounded-lg border border-slate-200 shadow-sm">
                   <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3">Design & Export</div>

                   <div className="mb-4">
                     {outline.coverImage ? (
                       <div className="relative group rounded-md overflow-hidden mb-2 border border-slate-100 shadow-sm">
                          <img src={`data:image/jpeg;base64,${outline.coverImage}`} alt="Cover" className="w-full h-full object-cover aspect-square" />
                          <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                             <button onClick={handleGenerateCover} className="text-white text-xs font-bold flex items-center gap-1 hover:underline">
                                <ImageIcon size={12} /> Regenerate
                             </button>
                          </div>
                       </div>
                     ) : (
                       <button 
                         onClick={handleGenerateCover}
                         disabled={isCoverGenerating}
                         className="w-full py-2 px-3 bg-purple-50 hover:bg-purple-100 text-purple-700 rounded-md text-xs font-bold flex items-center justify-center gap-2 transition-all mb-2"
                       >
                         {isCoverGenerating ? <Loader2 size={12} className="animate-spin" /> : <Sparkles size={12} />}
                         Generate Full Cover
                       </button>
                     )}
                   </div>

                   <button 
                     onClick={() => setIsPreviewOpen(true)}
                     className="w-full flex items-center gap-2 text-slate-600 hover:text-blue-700 hover:bg-slate-50 p-2 rounded-md text-sm font-medium transition-colors mb-1"
                   >
                     <Download size={16} />
                     Download E-Book (PDF)
                   </button>
                   <button 
                     onClick={handleExportDocs}
                     disabled={isExportingDocs}
                     className="w-full flex items-center gap-2 text-slate-600 hover:text-blue-700 hover:bg-slate-50 p-2 rounded-md text-sm font-medium transition-colors"
                   >
                     {isExportingDocs ? <Loader2 size={16} className="animate-spin" /> : <FileText size={16} />}
                     Export to Docs
                   </button>
                </div>
             </div>
          </div>

        </div>

        {/* Reader Content */}
        <div className="flex-1 flex flex-col h-full overflow-hidden bg-slate-50 relative w-full">

           <div className="md:hidden h-14 bg-white border-b border-slate-200 flex items-center px-4 shrink-0 justify-between">
              <button onClick={() => setIsSidebarOpen(true)} className="p-2 -ml-2 text-slate-600 hover:bg-slate-100 rounded-lg">
                 <Menu size={24} />
              </button>
              <span className="font-serif font-bold text-slate-900 truncate max-w-[200px]">
                 {currentChapter ? `Ch ${currentChapter.chapterNumber}: ${currentChapter.title}` : 'Reader'}
              </span>
              <div className="w-8"></div>
           </div>

           <div className="hidden md:block absolute top-4 left-4 z-20">
              <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 bg-white shadow-md rounded-lg border border-slate-200 text-slate-600 hover:text-blue-600 transition-colors">
                 {isSidebarOpen ? <ChevronLeft size={20} /> : <ChevronRight size={20} />}
              </button>
           </div>

           <div className="flex-1 overflow-y-auto p-4 md:p-12 scroll-smooth">
             <div className="max-w-3xl mx-auto bg-white shadow-xl shadow-slate-200/50 min-h-[80vh] p-6 md:p-16 rounded-xl relative border border-slate-100">

                <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-blue-100 via-blue-50 to-blue-100 opacity-50"></div>

                {!currentChapter ? (
                  <div className="flex flex-col items-center justify-center h-64 text-slate-400">
                    <Loader2 size={40} className="animate-spin mb-4 text-blue-200" />
                    <p>Loading Manuscript...</p>
                  </div>
                ) : (
                  <>
                    <div className="mb-8 pb-8 border-b border-slate-100">
                       <span className="text-xs font-bold tracking-[0.2em] text-slate-400 uppercase mb-2 block text-center">Chapter {currentChapter.chapterNumber}</span>
                       <h2 className="text-2xl md:text-4xl font-serif font-bold text-slate-900 text-center leading-tight">{currentChapter.title}</h2>
                    </div>

                    {isEditing ? (
                       <div className="animate-in fade-in">
                          <textarea 
                             value={editContent}
                             onChange={(e) => setEditContent(e.target.value)}
                             className="w-full h-[60vh] p-4 font-serif text-lg leading-relaxed text-slate-800 border-2 border-blue-100 rounded-lg outline-none focus:ring-2 focus:ring-blue-200 resize-y mb-4"
                          />

                          <div className="bg-blue-50 p-4 rounded-xl border border-blue-100 mb-6 flex gap-3 items-center">
                             <div className="bg-blue-200 p-2 rounded-full text-blue-700"><Wand2 size={16} /></div>
                             <div className="flex-1">
                                <input 
                                  value={polishInstruction}
                                  onChange={(e) => setPolishInstruction(e.target.value)}
                                  placeholder="Ask AI to polish (e.g., 'Make it more dramatic')"
                                  className="w-full bg-white border border-blue-200 rounded px-3 py-2 text-sm outline-none focus:border-blue-400"
                                  onKeyDown={(e) => e.key === 'Enter' && handlePolish()}
                                />
                             </div>
                             <button 
                               onClick={handlePolish}
                               disabled={isPolishing || !polishInstruction.trim()}
                               className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white text-sm font-bold rounded-lg transition-colors disabled:opacity-50"
                             >
                               {isPolishing ? <Loader2 size={16} className="animate-spin" /> : 'Refine'}
                             </button>
                          </div>

                          <div className="flex justify-end gap-3 sticky bottom-0 bg-white pt-4 border-t border-slate-100">
                             <button onClick={cancelEditing} className="px-5 py-2.5 text-slate-600 font-bold text-sm hover:bg-slate-100 rounded-lg">Cancel</button>
                             <button onClick={saveEditing} className="px-5 py-2.5 bg-emerald-600 hover:bg-emerald-500 text-white font-bold text-sm rounded-lg shadow-lg shadow-emerald-200 flex items-center gap-2">
                                <Save size={16} /> Save Changes
                             </button>
                          </div>
                       </div>
                    ) : (
                      <div className="prose prose-lg prose-slate font-serif max-w-none prose-headings:font-sans prose-headings:font-bold prose-p:leading-loose text-slate-800">
                         {currentChapter.isGenerating ? (
                           <div className="space-y-4 animate-pulse">
                              <div className="h-4 bg-slate-100 rounded w-full"></div>
                              <div className="h-4 bg-slate-100 rounded w-11/12"></div>
                              <div className="h-4 bg-slate-100 rounded w-full"></div>
                              <div className="py-8 text-center text-slate-400 text-sm font-sans flex items-center justify-center gap-2">
                                <Loader2 size={16} className="animate-spin" /> Writing in progress...
                              </div>
                           </div>
                         ) : (
                           <div className="relative group min-h-[200px]">
                              <ReactMarkdown>{currentChapter.content}</ReactMarkdown>
                              <button 
                                onClick={startEditing}
                                className="absolute top-0 right-0 p-2 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-lg opacity-0 group-hover:opacity-100 transition-all"
                                title="Edit Text"
                              >
                                <PenLine size={20} />
                              </button>
                           </div>
                         )}
                      </div>
                    )}
                  </>
                )}
             </div>

             <div className="max-w-3xl mx-auto mt-8 flex justify-between items-center text-sm font-medium text-slate-500 pb-24 md:pb-12 px-4">
                <button 
                  onClick={() => setCurrentChapterIndex(prev => Math.max(0, prev - 1))}
                  disabled={currentChapterIndex === 0}
                  className="flex items-center gap-2 hover:text-blue-600 disabled:opacity-30 disabled:hover:text-slate-500 transition-colors px-4 py-2 hover:bg-white rounded-full"
                >
                  <ChevronLeft size={16} /> Previous
                </button>
                <span>{currentChapterIndex + 1} / {chapters.length}</span>
                <button 
                  onClick={() => setCurrentChapterIndex(prev => Math.min(chapters.length - 1, prev + 1))}
                  disabled={currentChapterIndex === chapters.length - 1}
                  className="flex items-center gap-2 hover:text-blue-600 disabled:opacity-30 disabled:hover:text-slate-500 transition-colors px-4 py-2 hover:bg-white rounded-full"
                >
                  Next <ChevronRight size={16} />
                </button>
             </div>
           </div>
        </div>
      </div>
    </>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { ChapterContent, BookOutline } from '../types';
import { ChevronLeft, ChevronRight, Loader2, Download, PenLine, Save, Headphones, Play, Square, FileText, Image as ImageIcon, Wand2, Menu, X, Sparkles, Printer } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import { generateSpeech, generateImage, refineChapterText } from '../services/gemini';
import { Notification } from './Notification';

interface BookReaderProps {
  outline: BookOutline;
  chapters: ChapterContent[];
  onChapterUpdate?: (chapter: ChapterContent) => void;
  selectedVoice?: string;
  onVoiceChange?: (voice: string) => void;
  onUpdateOutline?: (outline: BookOutline) => void;
}

const DEFAULT_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbxntoxi2DILyS_K3zQlZx9DSUDMupWW9x_p4sfWkCsKzB1Yv38SVSaylfVIX_bAOp4_/exec";

// Audio Cache to prevent re-fetching
const audioCache = new Map<string, AudioBuffer>();

// Helpers for Gemini Audio (PCM)
function decode(base64: string) {
  try {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  } catch (e) {
    console.error("Audio decoding failed", e);
    return new Uint8Array(0);
  }
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number = 24000,
  numChannels: number = 1
): Promise<AudioBuffer> {
  // CRITICAL IOS FIX: Int16Array requires 2-byte alignment.
  // If the byte length is odd, we must slice it to make it even.
  let bufferToUse = data.buffer;
  let byteOffset = data.byteOffset;
  let byteLength = data.byteLength;

  if (byteLength % 2 !== 0) {
      const newBuffer = new Uint8Array(byteLength - 1);
      newBuffer.set(data.subarray(0, byteLength - 1));
      bufferToUse = newBuffer.buffer;
      byteOffset = 0;
      byteLength = newBuffer.byteLength;
  }

  const dataInt16 = new Int16Array(bufferToUse, byteOffset, byteLength / 2);
  const frameCount = dataInt16.length / numChannels;

  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

export const BookReader: React.FC<BookReaderProps> = ({ 
  outline, 
  chapters, 
  onChapterUpdate, 
  selectedVoice, 
  onVoiceChange,
  onUpdateOutline
}) => {
  const [currentChapterIndex, setCurrentChapterIndex] = useState(0);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isPlaying, setIsPlaying] = useState(false);
  const [audioLoading, setAudioLoading] = useState(false);
  const [isExportingDocs, setIsExportingDocs] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editContent, setEditContent] = useState('');
  const [polishInstruction, setPolishInstruction] = useState('');
  const [isPolishing, setIsPolishing] = useState(false);
  const [isCoverGenerating, setIsCoverGenerating] = useState(false);
  const [notification, setNotification] = useState<{message: string, type: 'error' | 'success'} | null>(null);

  // PDF Preview State
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);
  const [isPrinting, setIsPrinting] = useState(false);

  const audioContextRef = useRef<AudioContext | null>(null);
  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  const currentChapter = chapters[currentChapterIndex];

  useEffect(() => {
    stopAudio();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentChapterIndex]);

  const showNotification = (message: string, type: 'error' | 'success' = 'success') => {
    setNotification({ message, type });
    setTimeout(() => setNotification(null), 4000);
  };

  const stopAudio = () => {
    if (audioSourceRef.current) {
      try { audioSourceRef.current.stop(); } catch(e) {}
      audioSourceRef.current = null;
    }
    setIsPlaying(false);
  };

  const playChapterAudio = async () => {
    if (isPlaying) {
      stopAudio();
      return;
    }

    if (!currentChapter?.content) return;

    let silentSource: AudioBufferSourceNode | null = null;
    let ctx = audioContextRef.current;

    // --- iOS Audio Unlock Sequence ---
    try {
      if (!ctx) {
        // Handle standard and WebKit prefix for Safari
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
        ctx = new AudioContextClass();
        audioContextRef.current = ctx;
      }

      // Resume context immediately within the click handler
      if (ctx.state === 'suspended') {
        await ctx.resume();
      }

      // Play a short silent buffer to force the audio engine to wake up on iOS
      const silentBuffer = ctx.createBuffer(1, 1, 22050); 
      silentSource = ctx.createBufferSource();
      silentSource.buffer = silentBuffer;
      silentSource.connect(ctx.destination);
      silentSource.start();

    } catch (e) {
      console.error("Audio unlock failed", e);
      showNotification("Could not access audio hardware.", 'error');
      return;
    }

    const cacheKey = `${currentChapter.chapterNumber}-${selectedVoice}-${currentChapter.content.length}`;
    if (audioCache.has(cacheKey)) {
        if (silentSource) {
            try { (silentSource as AudioBufferSourceNode).stop(); } catch(e) {}
        }
        playBuffer(audioCache.get(cacheKey)!);
        return;
    }

    setAudioLoading(true);

    try {
      const pcmBase64 = await generateSpeech(currentChapter.content.slice(0, 5000), selectedVoice || 'Kore');

      // Re-check context existence
      if (!audioContextRef.current) {
          const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
          audioContextRef.current = new AudioContextClass();
      }
      ctx = audioContextRef.current!;

      const pcmData = decode(pcmBase64);
      const audioBuffer = await decodeAudioData(pcmData, ctx, 24000);

      audioCache.set(cacheKey, audioBuffer);

      if (silentSource) {
         try { (silentSource as AudioBufferSourceNode).stop(); } catch(e) {}
      }

      playBuffer(audioBuffer);

    } catch (err: any) {
      console.error("Audio playback failed", err);
      if (silentSource) {
        try { (silentSource as AudioBufferSourceNode).stop(); } catch(e) {}
      }
      showNotification("Failed to generate audio. " + (err.message || ""), 'error');
    } finally {
      setAudioLoading(false);
    }
  };

  const playBuffer = (buffer: AudioBuffer) => {
    const ctx = audioContextRef.current;
    if (!ctx) return;

    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.connect(ctx.destination);
    source.onended = () => setIsPlaying(false);

    audioSourceRef.current = source;
    source.start();
    setIsPlaying(true);
  };

  const handlePrint = () => {
    setIsPrinting(true);
    // Use a small timeout to allow UI to render 'Preparing' state
    // and ensure browser is ready to capture the specific print view
    setTimeout(() => {
      window.print();
      setIsPrinting(false);
    }, 100);
  };

  const handleExportDocs = async () => {
    setIsExportingDocs(true);

    const scriptUrl = prompt("Enter Google Apps Script URL:", DEFAULT_SCRIPT_URL);
    if (!scriptUrl) {
      setIsExportingDocs(false);
      return;
    }

    try {
      await fetch(scriptUrl, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title: outline.title,
          description: outline.description,
          chapters: chapters.map(c => ({
            chapterNumber: c.chapterNumber,
            title: c.title,
            content: c.content
          }))
        })
      });
      showNotification("Export request sent to Google Docs!");
    } catch (e) {
      console.error(e);
      showNotification("Docs export failed.", 'error');
    } finally {
      setIsExportingDocs(false);
    }
  };

  const startEditing = () => {
    if (!currentChapter) return;
    setEditContent(currentChapter.content);
    setIsEditing(true);
  };

  const saveEditing = () => {
    if (!currentChapter || !onChapterUpdate) return;
    onChapterUpdate({
      ...currentChapter,
      content: editContent
    });
    setIsEditing(false);
    showNotification("Changes saved.");
  };

  const cancelEditing = () => {
    setIsEditing(false);
    setPolishInstruction('');
  };

  const handlePolish = async () => {
    if (!polishInstruction.trim()) return;
    setIsPolishing(true);
    try {
      const polished = await refineChapterText(editContent, polishInstruction);
      setEditContent(polished);
      setPolishInstruction('');
      showNotification("Text refined!");
    } catch (e) {
      console.error(e);
      showNotification("Polish failed.", 'error');
    } finally {
      setIsPolishing(false);
    }
  };

  const handleGenerateCover = async () => {
    if (!onUpdateOutline) return;
    setIsCoverGenerating(true);
    try {
      const prompt = `Create a flat 2D front cover design for a book titled "${outline.title}". 
      Description: ${outline.description}. 
      Style: Minimalist, modern, striking typography, best-selling aesthetic.
      IMPORTANT: This must be a flat, rectangular 2D image suitable for printing. Do NOT render a 3D book object, do NOT show a book spine, and do NOT place the book on a table or background surface. Just the artwork itself.`;

      const base64Image = await generateImage(prompt, '3:4');
      onUpdateOutline({
        ...outline,
        coverImage: base64Image
      });
      showNotification("Cover updated!");
    } catch (e) {
      console.error(e);
      showNotification("Failed to generate cover.", 'error');
    } finally {
      setIsCoverGenerating(false);
    }
  };

  const handleChapterSelect = (idx: number) => {
    setCurrentChapterIndex(idx);
    if (window.innerWidth < 768) {
      setIsSidebarOpen(false);
    }
  };

  return (
    <>
      {notification && (
        <Notification message={notification.message} type={notification.type} onClose={() => setNotification(null)} />
      )}

      {/* --- PDF Preview Overlay --- */}
      {isPreviewOpen && (
        <div className="fixed inset-0 z-[100] bg-white overflow-y-auto animate-in fade-in duration-200">
          <style>
            {`
              @media print {
                /* 1. Reset Global Layout Constraints */
                html, body, #root {
                  height: auto !important;
                  width: 100% !important;
                  overflow: visible !important;
                  position: static !important;
                  margin: 0 !important;
                  padding: 0 !important;
                }

                /* 2. Hide everything by default using visibility */
                body {
                  visibility: hidden;
                }

                /* 3. Target our specific print content wrapper */
                #print-content {
                  visibility: visible !important;
                  position: absolute !important;
                  left: 0 !important;
                  top: 0 !important;
                  width: 100% !important;
                  margin: 0 !important;
                  padding: 0 !important;
                  background: white;
                  display: block !important;
                }

                /* 4. Ensure children are visible */
                #print-content * {
                  visibility: visible !important;
                }

                /* 5. Hide UI elements explicitly marked */
                .no-print {
                  display: none !important;
                }

                /* 6. Page setup */
                @page {
                  margin: 20mm;
                  size: auto;
                }

                /* 7. Typography fixes for print */
                .prose {
                  max-width: none !important;
                  color: black !important;
                  font-size: 12pt !important;
                  line-height: 1.5 !important;
                }

                h1, h2, h3 {
                  page-break-after: avoid;
                  color: black !important;
                }

                img {
                  max-width: 100% !important;
                }

                .page-break {
                  page-break-before: always;
                  min-height: 1px; /* Ensure break is respected */
                }
              }
            `}
          </style>

          {/* Print Toolbar */}
          <div className="sticky top-0 z-50 bg-slate-900 text-white p-4 flex justify-between items-center shadow-lg no-print">
            <div className="flex items-center gap-4">
                <button 
                  onClick={() => !isPrinting && setIsPreviewOpen(false)} 
                  disabled={isPrinting}
                  className="flex items-center gap-2 text-sm font-bold text-slate-300 hover:text-white disabled:opacity-50 transition-colors"
                >
                  <ChevronLeft size={16} /> Back to Editor
                </button>
                <div className="h-4 w-px bg-slate-700"></div>
                <span className="font-serif font-bold">{outline.title} (Preview)</span>
            </div>
            <button 
              onClick={handlePrint}
              disabled={isPrinting}
              className={`bg-blue-600 hover:bg-blue-500 text-white px-6 py-2 rounded-md font-bold text-sm flex items-center gap-2 shadow-sm transition-all ${isPrinting ? 'opacity-80 cursor-wait' : ''}`}
            >
              {isPrinting ? <Loader2 size={16} className="animate-spin" /> : <Printer size={16} />}
              {isPrinting ? 'Preparing PDF...' : 'Print / Save as PDF'}
            </button>
          </div>

          {/* Book Content (Print Layout) */}
          <div id="print-content" className="max-w-[800px] mx-auto bg-white p-12 md:p-24 min-h-screen shadow-2xl md:my-12 print:shadow-none print:p-0 print:m-0 print:w-full print:max-w-none">

            {/* Title Page */}
            <div className="flex flex-col items-center justify-center min-h-[800px] text-center page-break mb-24">
                <h1 className="text-5xl md:text-6xl font-serif font-bold text-slate-900 mb-6 leading-tight">{outline.title}</h1>
                <div className="w-16 h-1 bg-slate-900 mb-8"></div>
                <p className="text-sm uppercase tracking-[0.3em] text-slate-500 mb-12">A Lore Original</p>

                {outline.coverImage && (
                  <img src={`data:image/jpeg;base64,${outline.coverImage}`} className="w-64 h-auto aspect-[3/4] object-cover shadow-lg mb-12 print:shadow-none border border-slate-100" />
                )}

                <p className="max-w-md text-slate-600 italic font-serif leading-relaxed">{outline.description}</p>
            </div>

            {/* Chapters */}
            {chapters.map((chapter) => (
              <div key={chapter.chapterNumber} className="page-break mt-12">
                  <div className="text-center mb-12 mt-8">
                    <span className="text-xs font-bold uppercase tracking-widest border-b border-slate-300 pb-2 mb-4 inline-block">Chapter {chapter.chapterNumber}</span>
                    <h2 className="text-3xl font-serif font-bold text-slate-900">{chapter.title}</h2>
                  </div>

                  <div className="prose prose-lg prose-slate font-serif max-w-none text-justify leading-loose">
                    <ReactMarkdown>{chapter.content}</ReactMarkdown>
                  </div>
              </div>
            ))}

            <div className="text-center mt-24 pt-12 border-t border-slate-100 text-xs text-slate-400">
                Generated with Lore
            </div>
          </div>
        </div>
      )}

      {/* --- Main Editor (Hidden when previewing) --- */}
      <div className={`flex flex-col md:flex-row h-[calc(100vh-4rem)] bg-slate-50 relative overflow-hidden ${isPreviewOpen ? 'hidden' : ''}`}>

        {/* Sidebar */}
        <div className={`
            flex-col bg-white border-r border-slate-200 flex-shrink-0 transition-all duration-300 z-30
            ${isSidebarOpen ? 'fixed inset-0 w-full flex md:static md:w-80' : 'hidden md:flex md:w-0 md:overflow-hidden'}
        `}>
          <div className="p-6 border-b border-slate-100 flex-shrink-0 flex justify-between items-start">
             <div className="overflow-hidden">
               <h3 className="font-bold text-slate-900 font-serif mb-1 truncate">{outline.title}</h3>
               <p className="text-xs text-slate-500 uppercase tracking-wider font-semibold">Table of Contents</p>
             </div>
             <button onClick={() => setIsSidebarOpen(false)} className="md:hidden p-1 text-slate-400 hover:text-slate-600">
               <X size={24} />
             </button>
          </div>

          {/* Unified Scrollable Area: Holds both chapters and controls */}
          <div className="flex-1 overflow-y-auto">
             <div className="p-4 space-y-2">
               {chapters.map((chap, idx) => (
                 <button
                   key={chap.chapterNumber}
                   onClick={() => handleChapterSelect(idx)}
                   className={`w-full text-left p-3 rounded-lg text-sm transition-all border ${
                     currentChapterIndex === idx 
                     ? 'bg-blue-50 border-blue-200 text-blue-800 font-bold shadow-sm' 
                     : 'border-transparent hover:bg-slate-50 text-slate-600'
                   }`}
                 >
                   <div className="flex justify-between items-center mb-1">
                      <span className="text-xs opacity-70 uppercase tracking-wide">Chapter {chap.chapterNumber}</span>
                      {chap.isGenerating && <Loader2 size={12} className="animate-spin text-blue-500"/>}
                   </div>
                   <div className="truncate">{chap.title}</div>
                 </button>
               ))}
             </div>

             <div className="p-4 border-t border-slate-100 bg-slate-50/50 space-y-3">
                <div className="bg-white p-3 rounded-lg border border-slate-200 shadow-sm">
                   <div className="flex items-center gap-2 mb-2 text-xs font-bold text-slate-400 uppercase tracking-wider">
                     <Headphones size={12} /> Audiobook
                   </div>
                   <select 
                      value={selectedVoice}
                      onChange={(e) => onVoiceChange && onVoiceChange(e.target.value)}
                      className="w-full text-sm p-2 bg-slate-50 border border-slate-200 rounded mb-2 outline-none focus:border-blue-300"
                   >
                     <option value="Kore">Kore (Balanced)</option>
                     <option value="Puck">Puck (Energetic)</option>
                     <option value="Fenrir">Fenrir (Deep)</option>
                     <option value="Charon">Charon (Calm)</option>
                   </select>
                   <button 
                     onClick={playChapterAudio}
                     disabled={audioLoading || !currentChapter || currentChapter.isGenerating}
                     className={`w-full py-2 rounded-md font-bold text-sm text-white flex items-center justify-center gap-2 transition-all ${isPlaying ? 'bg-slate-800 hover:bg-slate-900' : 'bg-blue-600 hover:bg-blue-500 shadow-sm'}`}
                   >
                     {audioLoading ? <Loader2 size={14} className="animate-spin" /> : isPlaying ? <Square size={14} fill="currentColor" /> : <Play size={14} fill="currentColor" />}
                     {isPlaying ? 'Stop Reading' : 'Read Chapter'}
                   </button>
                </div>

                <div className="bg-white p-4 rounded-lg border border-slate-200 shadow-sm">
                   <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3">Design & Export</div>

                   <div className="mb-4">
                     {outline.coverImage ? (
                       <div className="relative group rounded-md overflow-hidden mb-2 border border-slate-100 shadow-sm">
                          <img src={`data:image/jpeg;base64,${outline.coverImage}`} alt="Cover" className="w-full h-auto aspect-[3/4] object-cover" />
                          <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                             <button onClick={handleGenerateCover} className="text-white text-xs font-bold flex items-center gap-1 hover:underline">
                                <ImageIcon size={12} /> Regenerate
                             </button>
                          </div>
                       </div>
                     ) : (
                       <button 
                         onClick={handleGenerateCover}
                         disabled={isCoverGenerating}
                         className="w-full py-2 px-3 bg-purple-50 hover:bg-purple-100 text-purple-700 rounded-md text-xs font-bold flex items-center justify-center gap-2 transition-all mb-2"
                       >
                         {isCoverGenerating ? <Loader2 size={12} className="animate-spin" /> : <Sparkles size={12} />}
                         Generate Full Cover
                       </button>
                     )}
                   </div>

                   <button 
                     onClick={() => setIsPreviewOpen(true)}
                     className="w-full flex items-center gap-2 text-slate-600 hover:text-blue-700 hover:bg-slate-50 p-2 rounded-md text-sm font-medium transition-colors mb-1"
                   >
                     <Download size={16} />
                     Download E-Book (PDF)
                   </button>
                   <button 
                     onClick={handleExportDocs}
                     disabled={isExportingDocs}
                     className="w-full flex items-center gap-2 text-slate-600 hover:text-blue-700 hover:bg-slate-50 p-2 rounded-md text-sm font-medium transition-colors"
                   >
                     {isExportingDocs ? <Loader2 size={16} className="animate-spin" /> : <FileText size={16} />}
                     Export to Docs
                   </button>
                </div>
             </div>
          </div>

        </div>

        {/* Reader Content */}
        <div className="flex-1 flex flex-col h-full overflow-hidden bg-slate-50 relative w-full">

           <div className="md:hidden h-14 bg-white border-b border-slate-200 flex items-center px-4 shrink-0 justify-between">
              <button onClick={() => setIsSidebarOpen(true)} className="p-2 -ml-2 text-slate-600 hover:bg-slate-100 rounded-lg">
                 <Menu size={24} />
              </button>
              <span className="font-serif font-bold text-slate-900 truncate max-w-[200px]">
                 {currentChapter ? `Ch ${currentChapter.chapterNumber}: ${currentChapter.title}` : 'Reader'}
              </span>
              <div className="w-8"></div>
           </div>

           <div className="hidden md:block absolute top-4 left-4 z-20">
              <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 bg-white shadow-md rounded-lg border border-slate-200 text-slate-600 hover:text-blue-600 transition-colors">
                 {isSidebarOpen ? <ChevronLeft size={20} /> : <ChevronRight size={20} />}
              </button>
           </div>

           <div className="flex-1 overflow-y-auto p-4 md:p-12 scroll-smooth">
             <div className="max-w-3xl mx-auto bg-white shadow-xl shadow-slate-200/50 min-h-[80vh] p-6 md:p-16 rounded-xl relative border border-slate-100">

                <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-blue-100 via-blue-50 to-blue-100 opacity-50"></div>

                {!currentChapter ? (
                  <div className="flex flex-col items-center justify-center h-64 text-slate-400">
                    <Loader2 size={40} className="animate-spin mb-4 text-blue-200" />
                    <p>Loading Manuscript...</p>
