                </div>
             </div>
          </div>
        </div>
      )}

      {/* --- Main Editor (Hidden when previewing) --- */}
      <div className={`flex flex-col md:flex-row h-[calc(100vh-4rem)] bg-slate-50 relative overflow-hidden ${isPreviewOpen ? 'hidden' : ''}`}>

        {/* Sidebar */}
        <div className={`
            flex-col bg-white border-r border-slate-200 flex-shrink-0 transition-all duration-300 z-30
